INSERT INTO public.american_amencontrast (lesson_id,us,uk,note_cn,ipa,example1,example1_cn,example2,example2_cn) VALUES ('am3_l42','lure down','',NULL,'/lʊr daʊn/','The chance of discovery lures people down into caves.','发现的机会把人引向洞穴深处。','The smell lured us into the kitchen.','香味把我们引进了厨房。') ON CONFLICT (lesson_id,us) DO UPDATE SET ipa=EXCLUDED.ipa,example1=EXCLUDED.example1,example1_cn=EXCLUDED.example1_cn,example2=EXCLUDED.example2,example2_cn=EXCLUDED.example2_cn;
INSERT INTO public.american_amencontrast (lesson_id,us,uk,note_cn,ipa,example1,example1_cn,example2,example2_cn) VALUES ('am3_l42','edge one''s way','',NULL,'/edʒ wʌnz weɪ/','They edged their way along the corridor.','他们侧身沿通道慢慢挪动。','She edged her way through the crowd.','她从人群中侧身挤过。') ON CONFLICT (lesson_id,us) DO UPDATE SET ipa=EXCLUDED.ipa,example1=EXCLUDED.example1,example1_cn=EXCLUDED.example1_cn,example2=EXCLUDED.example2,example2_cn=EXCLUDED.example2_cn;
INSERT INTO public.american_amencontrast (lesson_id,us,uk,note_cn,ipa,example1,example1_cn,example2,example2_cn) VALUES ('am3_l42','rig up','',NULL,'/rɪɡ ʌp/','It took days to rig up rope ladders.','搭好绳梯花了好几天。','They rigged up a shelter from branches.','他们用树枝临时搭了个棚。') ON CONFLICT (lesson_id,us) DO UPDATE SET ipa=EXCLUDED.ipa,example1=EXCLUDED.example1,example1_cn=EXCLUDED.example1_cn,example2=EXCLUDED.example2,example2_cn=EXCLUDED.example2_cn;
INSERT INTO public.american_amencontrast (lesson_id,us,uk,note_cn,ipa,example1,example1_cn,example2,example2_cn) VALUES ('am3_l42','switch on','',NULL,'/swɪtʃ ɑːn/','They switched on their powerful lights.','他们打开了强光灯。','Switch on the lamp, please.','请把灯打开。') ON CONFLICT (lesson_id,us) DO UPDATE SET ipa=EXCLUDED.ipa,example1=EXCLUDED.example1,example1_cn=EXCLUDED.example1_cn,example2=EXCLUDED.example2,example2_cn=EXCLUDED.example2_cn;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l42',5,'am3_l42_gp1','choice','{"stem":"\"It is the desire for solitude ___ lures people underground.\"(强调句 It is … ___ …)","options":["which does","that","what","and"],"answer_index":1,"stem_cn":"正是对独处的渴望,把人引向地下。","explanation_cn":"强调句 It is + 被强调部分 + that + 其余;被强调的是主语 the desire,连接词用 that。✓ It is the desire … that lures people. ✗ what / which does / and:强调句连接词用 that。"}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l42',5,'am3_l42_gp1','choice','{"stem":"\"It was in the Alps ___ the deepest cave was found.\"(强调地点,It was … ___ …)","options":["where","what","which","that"],"answer_index":3,"stem_cn":"正是在阿尔卑斯山,人们发现了最深的洞。","explanation_cn":"强调地点也用 It was … that …,不用 where。✓ It was in the Alps that the cave was found. ✗ where / which / what:强调句一律用 that。"}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l42',5,'am3_l42_gp1','choice','{"stem":"\"It is the cavers ___ explore the deepest caves.\"(强调人,It is … ___ …)","options":["what","who","which","whom"],"answer_index":1,"stem_cn":"正是洞穴探险者们探索着最深的洞。","explanation_cn":"强调的是人(the cavers),连接词可用 who。✓ It is the cavers who explore the caves. ✗ which(指物)/ whom(此处作主语不用宾格)/ what:强调人用 who。"}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l42',5,'am3_l42_gp2','choice','{"stem":"\"The cave might never have been discovered ___ not the entrance been spotted.\"(省略 if 的虚拟倒装,填助动词)","options":["would","has","had","did"],"answer_index":2,"stem_cn":"要不是有人发现了洞口,这个洞也许永远无人知晓。","explanation_cn":"与过去事实相反的虚拟条件,省略 if 时把 had 提到主语前倒装;填 had。✓ had not the entrance been spotted. ✗ has / did / would:虚拟倒装提前的是 had。"}'::jsonb,4) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l42',5,'am3_l42_gp2','choice','{"stem":"\"___ they planned more carefully, they would have gone deeper.\"(省略 if 的虚拟倒装:如果他们…)","options":["Did","Have","If had","Had"],"answer_index":3,"stem_cn":"若是计划得更周密,他们本可以下得更深。","explanation_cn":"同上,句首用 Had 引导倒装(=If they had planned)。✓ Had they planned more carefully, … ✗ If had(语序错)/ Did / Have:省略 if 用 Had 倒装。"}'::jsonb,5) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l42',5,'am3_l42_gp2','choice','{"stem":"\"If the stream had not tunneled the rock, the chasm ___ never have formed.\"(与过去事实相反,主句用 ___ have done)","options":["would","will","had","does"],"answer_index":0,"stem_cn":"要不是溪水冲蚀岩石,这陷坑根本不会形成。","explanation_cn":"与过去相反的虚拟主句用 would have done。✓ the chasm would never have formed. ✗ will / does / had:主句用 would have。"}'::jsonb,6) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l42',5,'am3_l42_gp3','choice','{"stem":"\"They heard a waterspout ___ down from the roof.\"(现在分词短语修饰 waterspout)","options":["shot","shoots","shooting","to shoot"],"answer_index":2,"stem_cn":"他们听见一股水柱从洞顶冲下。","explanation_cn":"现在分词短语放在名词后修饰它,表主动、正在进行;waterspout 自己往下冲,用 shooting。✓ a waterspout shooting down. ✗ shot / to shoot / shoots:修饰名词的主动分词用 -ing。"}'::jsonb,7) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l42',5,'am3_l42_gp3','choice','{"stem":"\"Great stalagmites, ___ up like tree trunks, filled the cavern.\"(现在分词短语修饰 stalagmites)","options":["rise","rising","risen","to rise"],"answer_index":1,"stem_cn":"一根根石笋像树干般拔地而起,布满大洞。","explanation_cn":"石笋自己升起,主动关系,用现在分词 rising 修饰 stalagmites。✓ stalagmites rising up. ✗ risen / to rise / rise:主动进行用 -ing。"}'::jsonb,8) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l42',5,'am3_l42_gp3','choice','{"stem":"\"They saw stalactites ___ from the roof.\"(分词修饰 stalactites:悬挂着的)","options":["to hang","hangs","hanging","hung by"],"answer_index":2,"stem_cn":"他们看见钟乳石从洞顶垂下。","explanation_cn":"钟乳石自己悬挂着,主动状态,用 hanging 修饰 stalactites。✓ stalactites hanging from the roof. ✗ hung by / to hang / hangs:主动状态用 -ing。"}'::jsonb,9) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l42',5,'am3_l42_gp4','choice','{"stem":"\"Cave exploration, ___ it has come to be known, is a new sport.\"(插入语\"正如已被人熟知的那样\")","options":["that","what","which","as"],"answer_index":3,"stem_cn":"洞穴勘查——正如现在人们所熟知的——是项新运动。","explanation_cn":"as it has come to be known 是插入语,\\\"正如已被人熟知的那样\\\",as 引导。✓ as it has come to be known. ✗ that / which / what:此插入语固定用 as。"}'::jsonb,10) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l42',5,'am3_l42_gp4','choice','{"stem":"\"The Gouffre Berger, ___ is near Grenoble, is very deep.\"(补充说明的从句,用哪个)","options":["which","that","what","it"],"answer_index":0,"stem_cn":"高弗·伯杰洞——它在格勒诺布尔附近——非常深。","explanation_cn":"补充说明的非限定从句,先行词是物(the Gouffre Berger),用 which。✓ the Gouffre Berger, which is near Grenoble. ✗ that(非限定不用)/ what / it:补充说明用 which。"}'::jsonb,11) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l42',5,'am3_l42_gp4','choice','{"stem":"\"The sound, ___ they found, came from a waterspout.\"(插入语\"他们发现\",用哪个)","options":["that","what","as","it"],"answer_index":2,"stem_cn":"那声音——他们发现——来自一股水柱。","explanation_cn":"as they found 作插入语,\\\"正如他们发现的那样\\\";与前文情况呼应用 as。✓ the sound, as they found, came from … ✗ that / what / it:此插入语用 as。"}'::jsonb,12) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l42',5,'am3_l42_gp5','choice','{"stem":"\"The cave ___ never have been found without Berger.\"(对过去的推测\"也许永远不会…\")","options":["can","might","may will","must to"],"answer_index":1,"stem_cn":"没有伯杰,这个洞也许永远不会被发现。","explanation_cn":"对过去的推测\\\"也许(永远不会)\\\"用 might have done。✓ might never have been found. ✗ may will / must to / can:对过去的可能推测用 might have。"}'::jsonb,13) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l42',5,'am3_l42_gp5','choice','{"stem":"\"They were exhausted; they ___ have walked for hours.\"(有把握地推测过去\"一定走了\")","options":["must","need","would to","can"],"answer_index":0,"stem_cn":"他们精疲力竭,一定走了好几个小时。","explanation_cn":"有把握地推测过去\\\"一定(做过)\\\"用 must have done。✓ they must have walked for hours. ✗ can / need / would to:肯定推测过去用 must have。"}'::jsonb,14) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l42',5,'am3_l42_gp5','choice','{"stem":"\"It''s a pity they didn''t go further; they ___ have reached the bottom.\"(\"本可以…却没有\")","options":["can","must","could","will"],"answer_index":2,"stem_cn":"可惜他们没再往前,本可以到达洞底。","explanation_cn":"\\\"本可以…却没有\\\"用 could have done。✓ they could have reached the bottom. ✗ can / must / will:与过去事实相反的\\\"本可\\\"用 could have。"}'::jsonb,15) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l42',5,'am3_l42_gp6','choice','{"stem":"\"To tempt or attract someone into doing something is to ___ them.\"(\"引诱、吸引\"用哪个词)","options":["lure","warn","calm","forbid"],"answer_index":0,"stem_cn":"引诱、吸引某人去做某事。","explanation_cn":"引诱、吸引某人是 lure。✓ lure people down into caves. ✗ warn 警告;✗ forbid 禁止;✗ calm 使平静——都不对。"}'::jsonb,16) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l42',5,'am3_l42_gp6','choice','{"stem":"\"The ability to plan wisely for the future is ___.\"(\"预见、深谋远虑\"用哪个词)","options":["memory","foresight","doubt","regret"],"answer_index":1,"stem_cn":"对未来明智筹划的能力。","explanation_cn":"对未来明智的筹划、远见是 foresight。✓ the planning and foresight of a military operation. ✗ memory 记忆;✗ regret 后悔;✗ doubt 怀疑——都不对。"}'::jsonb,17) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l42',5,'am3_l42_gp6','choice','{"stem":"\"A strange, frightening quietness in a dark place feels ___.\"(\"引起恐惧的、可怕的\"用哪个词)","options":["ordinary","cheerful","eerie","cozy"],"answer_index":2,"stem_cn":"黑暗处那种诡异、令人发怵的寂静。","explanation_cn":"诡异、令人发怵的是 eerie。✓ the eerie silence of the cavern. ✗ cozy 温馨;✗ cheerful 欢快;✗ ordinary 普通——都不对。"}'::jsonb,18) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l42',6,NULL,'choice','{"stem":"solitude 的意思是:","options":["合作","危险","孤独,独处","喧闹"],"answer_index":2,"explanation_cn":"solitude = 孤独、独处。✓ the desire for solitude 对独处的渴望。"}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l42',6,NULL,'choice','{"stem":"chasm 的意思是:","options":["断层,深坑","隧道","山峰","桥梁"],"answer_index":0,"explanation_cn":"chasm = 断层、深坑。✓ this immense chasm 这道巨大的陷坑。"}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l42',6,NULL,'choice','{"stem":"distinguished 的意思是:","options":["年轻的","无名的","普通的","杰出的,著名的"],"answer_index":3,"explanation_cn":"distinguished = 杰出的、著名的。✓ a distinguished French caver 一位著名的法国洞穴探险家。"}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l42',6,NULL,'choice','{"stem":"inflatable 的意思是:","options":["可充气的","透明的","沉重的","坚硬的"],"answer_index":0,"explanation_cn":"inflatable = 可充气的。✓ an inflatable rubber dinghy 一只充气橡皮艇。"}'::jsonb,4) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l42',6,NULL,'choice','{"stem":"cavern 的意思是:","options":["山顶","瀑布","大洞穴","沙漠"],"answer_index":2,"explanation_cn":"cavern = 大洞穴。✓ an enormous cavern 一个巨大的洞穴。"}'::jsonb,5) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l42',6,NULL,'choice','{"stem":"glisten 的意思是:","options":["闪烁,闪亮","破裂","熄灭","融化"],"answer_index":0,"explanation_cn":"glisten = 闪烁、闪亮。✓ piles of limestone glistened 一堆堆石灰石闪烁。"}'::jsonb,6) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l42',7,NULL,'cloze','{"stem":"第 1 空","context":"Cave exploration, ___1___ it has come to be known, is a fairly new sport. It is the desire for solitude ___2___ lures people underground. Deep caves are dangerous, and the deepest known cave might never ___3___ been found had not one caver spotted the entrance. Inside, cavers hear an insistent booming sound ___4___ by an underground waterspout.","blank_no":1,"options":["as","that","which","what"],"answer_index":0,"explanation_cn":"插入语 as it has come to be known,\\\"正如已被人熟知的那样\\\"。✓ caving, as it has come to be known."}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET payload=EXCLUDED.payload;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l42',7,NULL,'cloze','{"stem":"第 2 空","context":"Cave exploration, ___1___ it has come to be known, is a fairly new sport. It is the desire for solitude ___2___ lures people underground. Deep caves are dangerous, and the deepest known cave might never ___3___ been found had not one caver spotted the entrance. Inside, cavers hear an insistent booming sound ___4___ by an underground waterspout.","blank_no":2,"options":["that","what","which does","and"],"answer_index":0,"explanation_cn":"强调句 It is … that …,被强调的是 the desire for solitude。✓ It is the desire for solitude that lures people."}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET payload=EXCLUDED.payload;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l42',7,NULL,'cloze','{"stem":"第 3 空","context":"Cave exploration, ___1___ it has come to be known, is a fairly new sport. It is the desire for solitude ___2___ lures people underground. Deep caves are dangerous, and the deepest known cave might never ___3___ been found had not one caver spotted the entrance. Inside, cavers hear an insistent booming sound ___4___ by an underground waterspout.","blank_no":3,"options":["have","had","has","having"],"answer_index":0,"explanation_cn":"情态完成式的被动 might have been found;与倒装虚拟连用,填 have。✓ might never have been found."}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET payload=EXCLUDED.payload;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l42',7,NULL,'cloze','{"stem":"第 4 空","context":"Cave exploration, ___1___ it has come to be known, is a fairly new sport. It is the desire for solitude ___2___ lures people underground. Deep caves are dangerous, and the deepest known cave might never ___3___ been found had not one caver spotted the entrance. Inside, cavers hear an insistent booming sound ___4___ by an underground waterspout.","blank_no":4,"options":["caused","causing","cause","causes"],"answer_index":0,"explanation_cn":"过去分词短语修饰名词 sound,\\\"由…造成的\\\";被动关系用过去分词 caused。✓ a booming sound caused by a waterspout."}'::jsonb,4) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET payload=EXCLUDED.payload;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l42',8,NULL,'choice','{"stem":"What does the writer compare the Gouffre Berger to?","options":["A busy city","A sort of pot-holers'' Everest","A concert hall only","A wide river"],"answer_index":1,"explanation_cn":"录音把高弗·伯杰洞比作洞穴探险者的珠峰(最深、最向往)。✓ a sort of pot-holers'' Everest."}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l42',8,NULL,'choice','{"stem":"How did the team cross the underground lake?","options":["On an inflatable rubber dinghy","They walked around it","By swimming only","On a wooden raft"],"answer_index":0,"explanation_cn":"录音说他们把装备装上充气橡皮艇,让水流载着渡过地下湖。✓ on an inflatable rubber dinghy."}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l42',8,NULL,'choice','{"stem":"What was the only sound in the great cavern?","options":["Loud music","People shouting","Water dripping from the high dome","Birds singing"],"answer_index":2,"explanation_cn":"录音说洞穴一片诡异寂静,唯一声响是从高高穹顶滴落的水。✓ water dripping from the high dome."}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l42',9,NULL,'choice','{"stem":"你想说\"正是对独处的渴望把人引向地下\"(强调句):","options":["It the desire for solitude that lures people underground.","It is the desire for solitude which lures people underground it.","It is the desire for solitude what lures people underground.","It is the desire for solitude that lures people underground."],"answer_index":3,"explanation_cn":"强调句 It is + 被强调部分 + that + 其余,连接词用 that,不用 what/which。✓ It is the desire for solitude that lures people underground. 场合:强调\\\"正是…才…\\\"。"}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l42',9,NULL,'choice','{"stem":"你想说\"要不是有人发现了洞口,这个洞也许永远无人知晓\"(虚拟倒装):","options":["The cave might never been discovered had not the entrance be spotted.","The cave might never have been discovered had not the entrance been spotted.","The cave might never have discovered had not the entrance been spotted.","The cave might never have been discovered if not the entrance been spotted."],"answer_index":1,"explanation_cn":"与过去相反的虚拟条件,省略 if 把 had 提前倒装;主句 might have been done。✓ … had not the entrance been spotted. 场合:说\\\"要不是…就…\\\"。"}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l42',9,NULL,'choice','{"stem":"你想说\"没有伯杰,这个洞也许永远不会被发现\"(might have done):","options":["Without Berger, the cave might never has been found.","Without Berger, the cave may never had been found.","Without Berger, the cave might never have been found.","Without Berger, the cave might never have been find."],"answer_index":2,"explanation_cn":"对过去的推测用 might have been done(被动);be found 不能写成 be find。✓ might never have been found. 场合:说过去\\\"也许永远不会…\\\"。"}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l42',10,NULL,'choice','{"stem":"solitude 的意思是:","options":["喧闹","危险","合作","孤独,独处"],"answer_index":3,"explanation_cn":"solitude = 孤独、独处。✓ the desire for solitude."}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l42',10,NULL,'choice','{"stem":"eerie 的意思是:","options":["引起恐惧的,可怕的","欢快的","温馨的","普通的"],"answer_index":0,"explanation_cn":"eerie = 引起恐惧的、可怕的。✓ the eerie silence of the cavern."}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l42',10,NULL,'choice','{"stem":"\"It is the desire for solitude ___ lures people underground.\"(强调句 It is … ___ …)","options":["what","which does","and","that"],"answer_index":3,"stem_cn":"正是对独处的渴望,把人引向地下。","explanation_cn":"强调句 It is … that …,被强调的是主语 the desire,连接词用 that。✓ It is the desire … that lures people. ✗ what / which does / and:强调句用 that。"}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l42',10,NULL,'choice','{"stem":"\"The cave might never have been discovered ___ not the entrance been spotted.\"(省略 if 的虚拟倒装,填助动词)","options":["has","did","had","would"],"answer_index":2,"stem_cn":"要不是有人发现了洞口,这个洞也许永远无人知晓。","explanation_cn":"与过去相反的虚拟条件,省略 if 时把 had 提前倒装,填 had。✓ had not the entrance been spotted. ✗ has / did / would:虚拟倒装提前的是 had。"}'::jsonb,4) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l42',10,NULL,'choice','{"stem":"\"edge one''s way\" 的意思是:","options":["磨快刀刃","快速奔跑","走到边缘","侧身慢慢挪动"],"answer_index":3,"explanation_cn":"edge one''s way = 侧身、小心地慢慢挪动。✓ they edged their way along the corridor 他们侧身沿通道挪动。"}'::jsonb,5) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l42',10,NULL,'choice','{"stem":"\"rig up\" 的意思是:","options":["拆除","购买","临时搭建、装配","修理"],"answer_index":2,"explanation_cn":"rig up = (临时)搭建、装配。✓ rig up rope ladders 搭好绳梯。"}'::jsonb,6) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l42',10,NULL,'choice','{"stem":"Why is exploring deep caves compared to a military operation?","options":["It is a competition","It uses weapons","It is done by soldiers","It requires precise planning and foresight"],"answer_index":3,"passage":"Cave exploration, or caving, as it has come to be known, is a relatively new sport. Perhaps it is the desire for solitude, or the chance of making an unexpected discovery, that lures people down into the depths of the earth. It is impossible to give a satisfactory explanation for a caver''s motives. For him, caves hold the same peculiar fascination that high mountains hold for the climber; they arouse instincts that can only be dimly understood. Exploring really deep caves is not a task for the Sunday afternoon rambler. Such undertakings require the precise planning and foresight of a military operation. It can take as long as eight days to rig up rope ladders and set up supply bases before a descent can be made into a very deep cave. Precautions of this sort are necessary, for it is impossible to foretell the exact nature of the difficulties that will confront the caver. One of the deepest known caves in the world is the Gouffre Berger, near Grenoble, which reaches a depth of more than 3,700 feet. This immense chasm was formed by an underground stream that tunneled a course through a flaw in the rock. The entrance, high on a plateau in the Alps, is only about six feet across, so it is barely noticeable. The cave might never have been discovered had not the entrance been spotted by a distinguished French caver named Berger. A team of cavers recently went down the Gouffre Berger. After entering the narrow gap, they climbed down the steep sides until they reached a narrow corridor. They had to edge their way along it, sometimes wading across shallow streams or swimming across deep pools. Suddenly they came to a waterfall that dropped into an underground lake. They loaded their gear onto an inflatable rubber dinghy and let the current carry them across, wearing special rubber suits to protect themselves from the icy water. At the far end they could hear an insistent booming sound, which they found was caused by a small waterspout shooting down from the roof. Squeezing through a cleft in the rock, the cavers arrived at an enormous cavern, as large as a concert hall. When they switched on their powerful lights, they saw great stalagmites — some of them over forty feet high — rising up like tree trunks to meet the stalactites hanging from the roof. All around, piles of limestone glistened in every color of the rainbow. In the eerie silence of the cavern, the only sound was water dripping from the high dome above them.","explanation_cn":"课文说探深洞需要军事行动般的周密筹划和远见,故有此比。✓ requires the precise planning and foresight of a military operation."}'::jsonb,7) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l42',10,NULL,'choice','{"stem":"How was the immense chasm of the Gouffre Berger formed?","options":["By a volcano","By an underground stream tunneling through a flaw in the rock","By a sudden earthquake","By miners digging"],"answer_index":1,"passage":"Cave exploration, or caving, as it has come to be known, is a relatively new sport. Perhaps it is the desire for solitude, or the chance of making an unexpected discovery, that lures people down into the depths of the earth. It is impossible to give a satisfactory explanation for a caver''s motives. For him, caves hold the same peculiar fascination that high mountains hold for the climber; they arouse instincts that can only be dimly understood. Exploring really deep caves is not a task for the Sunday afternoon rambler. Such undertakings require the precise planning and foresight of a military operation. It can take as long as eight days to rig up rope ladders and set up supply bases before a descent can be made into a very deep cave. Precautions of this sort are necessary, for it is impossible to foretell the exact nature of the difficulties that will confront the caver. One of the deepest known caves in the world is the Gouffre Berger, near Grenoble, which reaches a depth of more than 3,700 feet. This immense chasm was formed by an underground stream that tunneled a course through a flaw in the rock. The entrance, high on a plateau in the Alps, is only about six feet across, so it is barely noticeable. The cave might never have been discovered had not the entrance been spotted by a distinguished French caver named Berger. A team of cavers recently went down the Gouffre Berger. After entering the narrow gap, they climbed down the steep sides until they reached a narrow corridor. They had to edge their way along it, sometimes wading across shallow streams or swimming across deep pools. Suddenly they came to a waterfall that dropped into an underground lake. They loaded their gear onto an inflatable rubber dinghy and let the current carry them across, wearing special rubber suits to protect themselves from the icy water. At the far end they could hear an insistent booming sound, which they found was caused by a small waterspout shooting down from the roof. Squeezing through a cleft in the rock, the cavers arrived at an enormous cavern, as large as a concert hall. When they switched on their powerful lights, they saw great stalagmites — some of them over forty feet high — rising up like tree trunks to meet the stalactites hanging from the roof. All around, piles of limestone glistened in every color of the rainbow. In the eerie silence of the cavern, the only sound was water dripping from the high dome above them.","explanation_cn":"课文说这道陷坑是地下暗流沿岩石裂缝冲蚀而成。✓ formed by an underground stream that tunneled through a flaw."}'::jsonb,8) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l42',10,NULL,'choice','{"stem":"How high were some of the stalagmites in the great cavern?","options":["About one foot","Ten inches","A hundred feet","Over forty feet high"],"answer_index":3,"audio":"Cave exploration, or caving, as it has come to be known, is a relatively new sport. Perhaps it is the desire for solitude, or the chance of making an unexpected discovery, that lures people down into the depths of the earth. It is impossible to give a satisfactory explanation for a caver''s motives. For him, caves hold the same peculiar fascination that high mountains hold for the climber; they arouse instincts that can only be dimly understood. Exploring really deep caves is not a task for the Sunday afternoon rambler. Such undertakings require the precise planning and foresight of a military operation. It can take as long as eight days to rig up rope ladders and set up supply bases before a descent can be made into a very deep cave. Precautions of this sort are necessary, for it is impossible to foretell the exact nature of the difficulties that will confront the caver. One of the deepest known caves in the world is the Gouffre Berger, near Grenoble, which reaches a depth of more than 3,700 feet. This immense chasm was formed by an underground stream that tunneled a course through a flaw in the rock. The entrance, high on a plateau in the Alps, is only about six feet across, so it is barely noticeable. The cave might never have been discovered had not the entrance been spotted by a distinguished French caver named Berger. A team of cavers recently went down the Gouffre Berger. After entering the narrow gap, they climbed down the steep sides until they reached a narrow corridor. They had to edge their way along it, sometimes wading across shallow streams or swimming across deep pools. Suddenly they came to a waterfall that dropped into an underground lake. They loaded their gear onto an inflatable rubber dinghy and let the current carry them across, wearing special rubber suits to protect themselves from the icy water. At the far end they could hear an insistent booming sound, which they found was caused by a small waterspout shooting down from the roof. Squeezing through a cleft in the rock, the cavers arrived at an enormous cavern, as large as a concert hall. When they switched on their powerful lights, they saw great stalagmites — some of them over forty feet high — rising up like tree trunks to meet the stalactites hanging from the roof. All around, piles of limestone glistened in every color of the rainbow. In the eerie silence of the cavern, the only sound was water dripping from the high dome above them.","explanation_cn":"录音说洞中石笋有的高达四十多英尺。✓ some of them over forty feet high."}'::jsonb,9) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l42',10,NULL,'choice','{"stem":"What did the cavers wear to protect themselves from the icy water?","options":["Special rubber suits","Metal armor","Nothing special","Wool coats"],"answer_index":0,"audio":"Cave exploration, or caving, as it has come to be known, is a relatively new sport. Perhaps it is the desire for solitude, or the chance of making an unexpected discovery, that lures people down into the depths of the earth. It is impossible to give a satisfactory explanation for a caver''s motives. For him, caves hold the same peculiar fascination that high mountains hold for the climber; they arouse instincts that can only be dimly understood. Exploring really deep caves is not a task for the Sunday afternoon rambler. Such undertakings require the precise planning and foresight of a military operation. It can take as long as eight days to rig up rope ladders and set up supply bases before a descent can be made into a very deep cave. Precautions of this sort are necessary, for it is impossible to foretell the exact nature of the difficulties that will confront the caver. One of the deepest known caves in the world is the Gouffre Berger, near Grenoble, which reaches a depth of more than 3,700 feet. This immense chasm was formed by an underground stream that tunneled a course through a flaw in the rock. The entrance, high on a plateau in the Alps, is only about six feet across, so it is barely noticeable. The cave might never have been discovered had not the entrance been spotted by a distinguished French caver named Berger. A team of cavers recently went down the Gouffre Berger. After entering the narrow gap, they climbed down the steep sides until they reached a narrow corridor. They had to edge their way along it, sometimes wading across shallow streams or swimming across deep pools. Suddenly they came to a waterfall that dropped into an underground lake. They loaded their gear onto an inflatable rubber dinghy and let the current carry them across, wearing special rubber suits to protect themselves from the icy water. At the far end they could hear an insistent booming sound, which they found was caused by a small waterspout shooting down from the roof. Squeezing through a cleft in the rock, the cavers arrived at an enormous cavern, as large as a concert hall. When they switched on their powerful lights, they saw great stalagmites — some of them over forty feet high — rising up like tree trunks to meet the stalactites hanging from the roof. All around, piles of limestone glistened in every color of the rainbow. In the eerie silence of the cavern, the only sound was water dripping from the high dome above them.","explanation_cn":"录音说他们穿特制橡胶服防冰冷湖水。✓ wearing special rubber suits."}'::jsonb,10) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_lessons (id,book_no,unit_no,lesson_no,title_en,title_cn,grammar_focus,scene,prelisten_question,grammar_card) VALUES ('am3_l43',3,9,43,'Fully Insured','全保险','the + 比较级, the + 比较级(越…越…)、so + 形容词 + that…(如此…以至于)、现在分词短语作状语(Shivering in their wet clothes, …)、have difficulty (in) doing / prove to be(结果证明是)、固定表达 in the event of / needless to say / make a claim for / put into operation(原创承载 NCE3 第三册 L43 考点·无需净化:保险题材幽默故事——小镇为年度集市定制的巨型馅饼盘投保、运河翻沉后打捞;美式化 county fair/tow truck/diner)','保险公司一般说来愿意承保几乎一切东西。承办公共或私人财产保险,在世界大部分地方都是正常业务。不过,倘若你要办一场户外聚会,同样可以为万一天气不好而给自己投保。不用说,保险公司承担的风险越大,你付的保险费也就越高。听说航运公司为打捞沉船提出索赔,这不算稀奇;可某个小镇为打捞一只沉下水的馅饼盘提出索赔,那才真是独一份。说真的,这只馅饼盘确实少见——足有十八英尺长、六英尺宽。它是小镇买下的,为的是在一年一度的县集市上烤一只巨大的馅饼。集市委员会认定,运这只盘子最好走运河,于是给这趟运输投了保。盘子刚下水不久,委员会成员就去当地一家小餐馆庆祝。就在这时,一群十几岁的孩子爬上盘子,开起了自己的小派对。跳起舞来,盘子实在承受不住,派对进行中它翻了个个儿,沉入七英尺深的水里。委员会给当地一家修车行老板打了电话,他开着一辆拖车赶来打捞。那些孩子穿着湿衣服冻得发抖,在一旁看着,三个工人一次次潜入水中寻找盘子。他们没费多大力就找到了,可要把它拖出水面却成了大难题。盘子四边太光滑,要在盘沿拴上缆索和链条又不弄坏它,几乎办不到。最后,链条固定在一端,一台大功率绞车开动起来。盘子浮出水面,被轻轻拖向河岸。有那么一个令人揪心的瞬间,盘子摇摇晃晃地悬在岸边,却突然失去平衡,又滑回水里。这一次,工人们用沉重的金属夹子把盘子两侧夹住,以便挂上链条。绞车再次启动,一名工人发动了拖车。几分钟后,盘子被成功地拖出水面。水从盘子两侧成股涌下,来势之猛,在运河里掀起一股大浪。有个危险是:大浪会从对岸弹回,再把盘子拖进水里。工人们以极快的速度抢干,终于赶在大浪返回之前把盘子弄上了岸。','{"q":"Listen and answer — Who owned the pie pan and why?","options":["A small town, to bake a giant pie for the annual fair","A shipping company, to carry cargo","A restaurant, to serve its customers","A museum, to display it"],"answer_index":0}'::jsonb,'{"title":"the + 比较级…the + 比较级 / so…that / 现在分词作状语 / have difficulty doing / 固定表达","intro":"①the + 比较级 + …, the + 比较级 + …:两件事同增同减,“越…越…”:The bigger the risk, the higher the premium。②so + 形容词/副词 + that + 结果:如此…以至于…:so smooth that chains would not hold。③现在分词短语放句首作状语,说明主语的伴随/原因:Shivering in their wet clothes, the teenagers looked on。④have difficulty (in) doing:做某事有困难;prove to be:结果证明是。⑤固定表达:in the event of(万一)、needless to say(不用说)、make a claim for(要求得到)、put into operation(使运转)。","table":{"headers":["用法","意思","例子"],"rows":[["the + 比较级, the + 比较级","越…越…","The bigger …, the higher …"],["so + 形容词 + that","如此…以至于","so smooth that chains slipped"],["现在分词短语作状语","伴随/原因","Shivering …, the teenagers looked on"],["in the event of / make a claim for","万一 / 要求得到","in the event of bad weather"]]},"specialRules":[{"rule":"the + 比较级结构里,两个 the 都不能省;比较级前面别再加 more（× the more big，√ the bigger）。","mark":"the bigger … the higher"},{"rule":"so 后接形容词/副词（so smooth），such 后接名词（such a smooth dish）;结果都用 that 引导。","mark":"so … that / such … that"},{"rule":"美式:county fair(英式 fete)、tow truck(英式 recovery truck)、diner(小餐馆)。本课已按美语写。","mark":"county fair / tow truck"}]}'::jsonb) ON CONFLICT (id) DO UPDATE SET book_no=EXCLUDED.book_no,title_en=EXCLUDED.title_en,title_cn=EXCLUDED.title_cn,grammar_focus=EXCLUDED.grammar_focus,scene=EXCLUDED.scene,prelisten_question=EXCLUDED.prelisten_question,grammar_card=EXCLUDED.grammar_card;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am3_l43',1,NULL,'Insurance companies are normally willing to insure almost anything. Insuring public or private property is standard practice in most parts of the world. If, however, you were holding an outdoor party, you could just as easily insure yourself in the event of bad weather. Needless to say, the bigger the risk an insurance company takes, the higher the premium you will have to pay.','保险公司一般说来愿意承保几乎一切东西。承办公共或私人财产保险,在世界大部分地方都是正常业务。不过,倘若你要办一场户外聚会,同样可以为万一天气不好而给自己投保。不用说,保险公司承担的风险越大,你付的保险费也就越高。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am3_l43',2,NULL,'It is not unusual to hear that a shipping company has made a claim for the cost of salvaging a sunken ship. But a claim made by a small town to recover the cost of salvaging a sunken pie pan must surely be one of a kind. Admittedly, it was an unusual pie pan, for it was eighteen feet long and six feet wide. It had been purchased by the town so that an enormous pie could be baked for the annual county fair.','听说航运公司为打捞沉船提出索赔,这不算稀奇;可某个小镇为打捞一只沉下水的馅饼盘提出索赔,那才真是独一份。说真的,这只馅饼盘确实少见——足有十八英尺长、六英尺宽。它是小镇买下的,为的是在一年一度的县集市上烤一只巨大的馅饼。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am3_l43',3,NULL,'The fair committee decided that the best way to move the pan would be by canal, so they insured it for the trip. Shortly after it was launched, the committee went off to a local diner to celebrate. Meanwhile, a group of teenagers climbed onto the pan and held a little party of their own. The dancing proved to be more than the pan could bear, for during the party it capsized and sank in seven feet of water.','集市委员会认定,运这只盘子最好走运河,于是给这趟运输投了保。盘子刚下水不久,委员会成员就去当地一家小餐馆庆祝。就在这时,一群十几岁的孩子爬上盘子,开起了自己的小派对。跳起舞来,盘子实在承受不住,派对进行中它翻了个个儿,沉入七英尺深的水里。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am3_l43',4,NULL,'The committee called a local garage owner, who showed up in a tow truck to salvage the pan. Shivering in their wet clothes, the teenagers looked on while three men dove again and again into the water to locate it. They had little difficulty finding it, but hauling it out proved to be a serious problem. The sides of the pan were so smooth that it was almost impossible to attach cables and chains to the rim without denting it. Eventually chains were fixed to one end and a powerful winch was put into operation.','委员会给当地一家修车行老板打了电话,他开着一辆拖车赶来打捞。那些孩子穿着湿衣服冻得发抖,在一旁看着,三个工人一次次潜入水中寻找盘子。他们没费多大力就找到了,可要把它拖出水面却成了大难题。盘子四边太光滑,要在盘沿拴上缆索和链条又不弄坏它,几乎办不到。最后,链条固定在一端,一台大功率绞车开动起来。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am3_l43',5,NULL,'The pan rose to the surface and was gently drawn toward the bank. For one agonizing moment it was perched precariously on the edge, but it suddenly overbalanced and slid back into the water. This time the men clamped heavy metal grips to both sides so that they could fasten the chains. The winch was started again, and one of the men fired up the truck. Several minutes later the pan was hauled clear of the surface. Water streamed off its sides in torrents, with such force that it set up a huge wave in the canal. There was a danger that the wave would rebound off the far bank and send the pan plunging in again. Working at tremendous speed, the men managed to get the pan onto dry land before the wave returned.','盘子浮出水面,被轻轻拖向河岸。有那么一个令人揪心的瞬间,盘子摇摇晃晃地悬在岸边,却突然失去平衡,又滑回水里。这一次,工人们用沉重的金属夹子把盘子两侧夹住,以便挂上链条。绞车再次启动,一名工人发动了拖车。几分钟后,盘子被成功地拖出水面。水从盘子两侧成股涌下,来势之猛,在运河里掀起一股大浪。有个危险是:大浪会从对岸弹回,再把盘子拖进水里。工人们以极快的速度抢干,终于赶在大浪返回之前把盘子弄上了岸。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
