INSERT INTO public.american_amencontrast (lesson_id,us,uk,note_cn,ipa,example1,example1_cn,example2,example2_cn) VALUES ('am3_l43','put into operation','',NULL,'/pʊt ˈɪntə ˌɑːpəˈreɪʃən/','A powerful winch was put into operation.','一台大功率绞车开动起来。','The new plan was put into operation last week.','新方案上周开始实施。') ON CONFLICT (lesson_id,us) DO UPDATE SET ipa=EXCLUDED.ipa,example1=EXCLUDED.example1,example1_cn=EXCLUDED.example1_cn,example2=EXCLUDED.example2,example2_cn=EXCLUDED.example2_cn;
INSERT INTO public.american_amencontrast (lesson_id,us,uk,note_cn,ipa,example1,example1_cn,example2,example2_cn) VALUES ('am3_l43','look on','',NULL,'/lʊk ɑːn/','The teenagers looked on while the men worked.','工人干活时,那些孩子在一旁看着。','A crowd looked on as the fire spread.','火蔓延时,一群人在旁观看。') ON CONFLICT (lesson_id,us) DO UPDATE SET ipa=EXCLUDED.ipa,example1=EXCLUDED.example1,example1_cn=EXCLUDED.example1_cn,example2=EXCLUDED.example2,example2_cn=EXCLUDED.example2_cn;
INSERT INTO public.american_amencontrast (lesson_id,us,uk,note_cn,ipa,example1,example1_cn,example2,example2_cn) VALUES ('am3_l43','make a claim for','',NULL,'/meɪk ə kleɪm fɔːr/','The company made a claim for the cost of salvage.','公司要求补偿打捞费用。','You can make a claim for the damage.','你可以就损失提出索赔。') ON CONFLICT (lesson_id,us) DO UPDATE SET ipa=EXCLUDED.ipa,example1=EXCLUDED.example1,example1_cn=EXCLUDED.example1_cn,example2=EXCLUDED.example2,example2_cn=EXCLUDED.example2_cn;
INSERT INTO public.american_amencontrast (lesson_id,us,uk,note_cn,ipa,example1,example1_cn,example2,example2_cn) VALUES ('am3_l43','set up','',NULL,'/set ʌp/','The falling water set up a huge wave.','落下的水掀起一股大浪。','His words set up a wave of excitement.','他的话激起一阵兴奋。') ON CONFLICT (lesson_id,us) DO UPDATE SET ipa=EXCLUDED.ipa,example1=EXCLUDED.example1,example1_cn=EXCLUDED.example1_cn,example2=EXCLUDED.example2,example2_cn=EXCLUDED.example2_cn;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l43',5,'am3_l43_gp1','choice','{"stem":"\"The bigger the risk, the ___ the premium.\"(the + 比较级, the + 比较级:越…越…)","options":["highest","high","more high","higher"],"answer_index":3,"stem_cn":"风险越大,保险费越高。","explanation_cn":"the + 比较级, the + 比较级,“越…越…”;后半也要 the + 比较级,high 的比较级是 higher。✓ the bigger …, the higher … ✗ high(缺比较级)/ highest(最高级)/ more high(错误变形)。"}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l43',5,'am3_l43_gp1','choice','{"stem":"\"The ___ you practice, the better you get.\"(前半也用 the + 比较级,填 much 的比较级)","options":["many","most","more","much"],"answer_index":2,"stem_cn":"练得越多,越进步。","explanation_cn":"前半同样用 the + 比较级;much 的比较级是 more。✓ The more you practice, … ✗ most(最高级)/ much(原级)/ many(修饰可数,此处不当)。"}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l43',5,'am3_l43_gp1','choice','{"stem":"\"The heavier the pan, the ___ it was to lift.\"(后半用 hard 的比较级)","options":["hardest","more hard","hard","harder"],"answer_index":3,"stem_cn":"盘子越重,越难抬起。","explanation_cn":"后半 the + 比较级;hard 的比较级是 harder。✓ the harder it was to lift. ✗ hard(原级)/ hardest(最高级)/ more hard(错误变形)。"}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l43',5,'am3_l43_gp2','choice','{"stem":"\"The sides were ___ smooth that no chain would hold.\"(“如此…以至于”,程度副词)","options":["such","very","so","too"],"answer_index":2,"stem_cn":"盘边太光滑,链子挂不住。","explanation_cn":"so + 形容词/副词 + that,表“如此…以至于”;smooth 是形容词,前用 so。✓ so smooth that … ✗ such(接名词)/ very(不接 that 结果)/ too(too…to 结构不同)。"}'::jsonb,4) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l43',5,'am3_l43_gp2','choice','{"stem":"\"It was such a heavy pan ___ four men could hardly move it.\"(such a + 名词 + …,填引导结果的那个词)","options":["which","as","so","that"],"answer_index":3,"stem_cn":"盘子太重,四个人都几乎搬不动。","explanation_cn":"such a + 名词 + that + 结果;引导结果的连词用 that。✓ such a heavy pan that four men … ✗ so(此处已用 such)/ as / which:引导结果用 that。"}'::jsonb,5) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l43',5,'am3_l43_gp2','choice','{"stem":"\"The wave was so strong ___ it nearly pushed the pan back.\"(so + 形容词 + …,填引导结果的那个词)","options":["than","so","that","as"],"answer_index":2,"stem_cn":"浪太猛,差点把盘子推回水里。","explanation_cn":"so + 形容词 + that + 结果;引导结果分句用 that。✓ so strong that it nearly … ✗ as / than / so:结果分句用 that。"}'::jsonb,6) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l43',5,'am3_l43_gp3','choice','{"stem":"\"___ in their wet clothes, the teenagers looked on.\"(现在分词短语作状语:冻得发抖)","options":["Shivered","Shivering","Shiver","To shiver"],"answer_index":1,"stem_cn":"那些孩子穿着湿衣服冻得发抖,在一旁看着。","explanation_cn":"现在分词短语放句首作状语,说明主语 teenagers 的伴随状态“冻得发抖”;主语主动,用现在分词。✓ Shivering in their wet clothes, the teenagers … ✗ Shiver / Shivered / To shiver:作状语的主动分词用 -ing。"}'::jsonb,7) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l43',5,'am3_l43_gp3','choice','{"stem":"\"___ at tremendous speed, the men saved the pan.\"(现在分词短语作状语:以极快速度干)","options":["Work","Worked","Working","To work"],"answer_index":2,"stem_cn":"工人们以极快的速度干,救下了盘子。","explanation_cn":"同理,现在分词短语作状语“以极快速度干”;主语 men 主动,用 Working。✓ Working at tremendous speed, the men … ✗ Work / Worked / To work:主动伴随用 -ing。"}'::jsonb,8) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l43',5,'am3_l43_gp3','choice','{"stem":"\"The men dove in, ___ for the sunken pan.\"(现在分词表伴随:一边找)","options":["searching","to search","searched","search"],"answer_index":0,"stem_cn":"工人们跳进水里,一边寻找沉下的盘子。","explanation_cn":"现在分词表伴随动作“一边找”;与主语 men 主动同时,用 searching。✓ The men dove in, searching for the pan. ✗ searched / to search / search:伴随用 -ing。"}'::jsonb,9) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l43',5,'am3_l43_gp4','choice','{"stem":"\"They had little difficulty ___ the pan.\"(have difficulty (in) doing 后接动名词)","options":["to find","found","finding","find"],"answer_index":2,"stem_cn":"他们没费什么力就找到了盘子。","explanation_cn":"have difficulty (in) doing sth,“做某事有困难”,后接动名词。✓ had little difficulty finding it. ✗ to find / find / found:该结构后跟 -ing。"}'::jsonb,10) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l43',5,'am3_l43_gp4','choice','{"stem":"\"Hauling it out ___ to be a serious problem.\"(“结果证明是…”,用过去式)","options":["proving","prove","proves","proved"],"answer_index":3,"stem_cn":"把它拖出来结果成了大难题。","explanation_cn":"prove to be,“结果证明是”;句子讲过去,用过去式 proved。✓ Hauling it out proved to be a problem. ✗ proves(现在)/ proving / prove:讲过去用 proved。"}'::jsonb,11) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l43',5,'am3_l43_gp4','choice','{"stem":"\"The dancing proved ___ more than the pan could bear.\"(prove 后接的不定式形式)","options":["be","to be","been","being"],"answer_index":1,"stem_cn":"跳舞结果超出了盘子能承受的。","explanation_cn":"prove 后接不定式 to be,“结果证明是…”。✓ proved to be more than the pan could bear. ✗ being / be / been:prove 后用 to be。"}'::jsonb,12) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l43',5,'am3_l43_gp5','choice','{"stem":"\"You can insure yourself ___ the event of bad weather.\"(固定短语 ___ the event of,“万一、倘若”,填介词)","options":["in","on","at","for"],"answer_index":0,"stem_cn":"你可以为万一天气不好而投保。","explanation_cn":"固定短语 in the event of,“万一、倘若发生”;介词用 in。✓ in the event of bad weather. ✗ on / at / for:固定搭配是 in the event of。"}'::jsonb,13) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l43',5,'am3_l43_gp5','choice','{"stem":"\"___ to say, bigger risks mean higher premiums.\"(“不用说”,___ to say,填形容词)","options":["Need not","Needing","No need","Needless"],"answer_index":3,"stem_cn":"不用说,风险越大保费越高。","explanation_cn":"Needless to say,“不用说、显然”;固定用形容词 needless。✓ Needless to say, … ✗ Needing / Need not / No need:固定说法是 Needless to say。"}'::jsonb,14) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l43',5,'am3_l43_gp5','choice','{"stem":"\"The shipping company made a claim ___ the cost of salvage.\"(make a claim ___,“要求得到”,填介词)","options":["for","of","with","to"],"answer_index":0,"stem_cn":"航运公司要求补偿打捞费用。","explanation_cn":"make a claim for sth,“要求得到、就…索赔”;介词用 for。✓ made a claim for the cost. ✗ of / to / with:make a claim 搭配 for。"}'::jsonb,15) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l43',5,'am3_l43_gp6','choice','{"stem":"\"To pull something heavy with effort is to ___ it.\"(“(用力)拖、拉”用哪个词)","options":["throw","haul","catch","drop"],"answer_index":1,"stem_cn":"用力拖拉某重物。","explanation_cn":"用力拖、拉重物是 haul。✓ haul it out of the water. ✗ drop 掉落;✗ throw 扔;✗ catch 接住——都不对。"}'::jsonb,16) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l43',5,'am3_l43_gp6','choice','{"stem":"\"When a boat turns over in the water, it has ___.\"(“(船)倾覆、翻”用哪个词)","options":["capsized","sailed","floated","docked"],"answer_index":0,"stem_cn":"船在水里翻了。","explanation_cn":"(船、盘)在水中倾覆、翻是 capsize。✓ the pan capsized and sank. ✗ floated 漂浮;✗ sailed 航行;✗ docked 停靠——都不对。"}'::jsonb,17) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l43',5,'am3_l43_gp6','choice','{"stem":"\"Money paid regularly for an insurance policy is the ___.\"(“保险费”用哪个词)","options":["wage","tax","fine","premium"],"answer_index":3,"stem_cn":"为保险定期支付的钱。","explanation_cn":"为保险定期支付的钱是 premium(保险费)。✓ the higher the premium you pay. ✗ wage 工资;✗ tax 税;✗ fine 罚款——都不对。"}'::jsonb,18) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l43',6,NULL,'choice','{"stem":"insure 的意思是:","options":["丢弃","出售","给…保险,投保","借出"],"answer_index":2,"explanation_cn":"insure = 给…保险、投保。✓ willing to insure almost anything 愿意承保几乎一切。"}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l43',6,NULL,'choice','{"stem":"annual 的意思是:","options":["每天的","一年一度的","永久的","临时的"],"answer_index":1,"explanation_cn":"annual = 一年一度的。✓ the annual county fair 一年一度的县集市。"}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l43',6,NULL,'choice','{"stem":"capsize 的意思是:","options":["加速","装载","(船)倾覆,翻","停泊"],"answer_index":2,"explanation_cn":"capsize = (船)倾覆、翻。✓ it capsized and sank 它翻了并沉没。"}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l43',6,NULL,'choice','{"stem":"overbalance 的意思是:","options":["充气","称重","固定","失去平衡"],"answer_index":3,"explanation_cn":"overbalance = 失去平衡。✓ it suddenly overbalanced 它突然失去平衡。"}'::jsonb,4) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l43',6,NULL,'choice','{"stem":"precariously 的意思是:","options":["缓慢地","危险地,不稳固地","安全地","整齐地"],"answer_index":1,"explanation_cn":"precariously = 危险地、不稳固地。✓ perched precariously on the edge 摇摇晃晃地悬在边上。"}'::jsonb,5) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l43',6,NULL,'choice','{"stem":"rebound 的意思是:","options":["弹回","燃烧","融化","下沉"],"answer_index":0,"explanation_cn":"rebound = 弹回。✓ the wave would rebound off the bank 浪会从岸边弹回。"}'::jsonb,6) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l43',7,NULL,'cloze','{"stem":"第 1 空","context":"Insurance companies will insure almost anything. Needless to say, the bigger the risk, the ___1___ the premium you pay. One small town even made a claim ___2___ the cost of salvaging a giant pie pan that had capsized in a canal. The pan''s sides were ___3___ smooth that chains would hardly hold. In the end a powerful winch was put ___4___ operation and the pan was hauled out.","blank_no":1,"options":["higher","high","highest","more high"],"answer_index":0,"explanation_cn":"the + 比较级, the + 比较级;后半用 higher。✓ the bigger the risk, the higher the premium."}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET payload=EXCLUDED.payload;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l43',7,NULL,'cloze','{"stem":"第 2 空","context":"Insurance companies will insure almost anything. Needless to say, the bigger the risk, the ___1___ the premium you pay. One small town even made a claim ___2___ the cost of salvaging a giant pie pan that had capsized in a canal. The pan''s sides were ___3___ smooth that chains would hardly hold. In the end a powerful winch was put ___4___ operation and the pan was hauled out.","blank_no":2,"options":["for","of","to","at"],"answer_index":0,"explanation_cn":"make a claim for,“要求得到、就…索赔”,介词 for。✓ made a claim for the cost of salvaging."}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET payload=EXCLUDED.payload;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l43',7,NULL,'cloze','{"stem":"第 3 空","context":"Insurance companies will insure almost anything. Needless to say, the bigger the risk, the ___1___ the premium you pay. One small town even made a claim ___2___ the cost of salvaging a giant pie pan that had capsized in a canal. The pan''s sides were ___3___ smooth that chains would hardly hold. In the end a powerful winch was put ___4___ operation and the pan was hauled out.","blank_no":3,"options":["so","such","very","too"],"answer_index":0,"explanation_cn":"so + 形容词 + that,“如此…以至于”;smooth 是形容词,用 so。✓ so smooth that chains would hardly hold."}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET payload=EXCLUDED.payload;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l43',7,NULL,'cloze','{"stem":"第 4 空","context":"Insurance companies will insure almost anything. Needless to say, the bigger the risk, the ___1___ the premium you pay. One small town even made a claim ___2___ the cost of salvaging a giant pie pan that had capsized in a canal. The pan''s sides were ___3___ smooth that chains would hardly hold. In the end a powerful winch was put ___4___ operation and the pan was hauled out.","blank_no":4,"options":["into","in","on","to"],"answer_index":0,"explanation_cn":"put into operation,“使运转、开动”;介词 into。✓ a winch was put into operation."}'::jsonb,4) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET payload=EXCLUDED.payload;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l43',8,NULL,'choice','{"stem":"Who owned the pie pan?","options":["A shipping company","The garage owner","A small town (the local authority)","The teenagers"],"answer_index":2,"explanation_cn":"录音说这只盘子是小镇(当地当局)为县集市买来烤大馅饼的。✓ owned by a small town."}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l43',8,NULL,'choice','{"stem":"Why did the pan sink?","options":["Teenagers danced on it and it capsized","It was too heavy to float","A storm hit the canal","Someone cut a hole in it"],"answer_index":0,"explanation_cn":"录音说一群青少年爬上盘子跳舞,盘子承受不住而倾覆下沉。✓ capsized during the dancing."}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l43',8,NULL,'choice','{"stem":"How was the pan finally lifted out?","options":["With a helicopter","By hand","It floated up on its own","With chains and a powerful winch"],"answer_index":3,"explanation_cn":"录音说最后用链条固定、开动大功率绞车才把盘子拖出。✓ chains and a powerful winch."}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l43',9,NULL,'choice','{"stem":"你想说\"风险越大,保费越高\"(the + 比较级, the + 比较级):","options":["Bigger the risk, higher the premium.","The bigger the risk, the higher the premium.","The bigger risk, the higher premium.","The more big the risk, the more high the premium."],"answer_index":1,"explanation_cn":"the + 比较级, the + 比较级,两个 the 都不能省,比较级前不再加 more。✓ The bigger the risk, the higher the premium. 场合:表达“越…越…”。"}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l43',9,NULL,'choice','{"stem":"你想说\"盘边太光滑,链子挂不住\"(so + 形容词 + that):","options":["The sides were so smooth that the chains would not hold.","The sides were too smooth that the chains would not hold.","The sides were so smooth as the chains would not hold.","The sides were such smooth that the chains would not hold."],"answer_index":0,"explanation_cn":"so + 形容词 + that + 结果;smooth 用 so 不用 such,结果用 that 不用 as。✓ so smooth that the chains would not hold. 场合:表达“如此…以至于”。"}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l43',9,NULL,'choice','{"stem":"你想说\"你可以为万一天气不好而投保\"(in the event of):","options":["You can insure yourself on the event of bad weather.","You can insure yourself in event of bad weather.","You can insure yourself in the case bad weather.","You can insure yourself in the event of bad weather."],"answer_index":3,"explanation_cn":"固定短语 in the event of,介词 in、冠词 the 都不能少。✓ in the event of bad weather. 场合:表达“万一发生…”。"}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l43',10,NULL,'choice','{"stem":"premium 的意思是:","options":["工资","税款","保险费","罚款"],"answer_index":2,"explanation_cn":"premium = 保险费。✓ the higher the premium you pay."}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l43',10,NULL,'choice','{"stem":"capsize 的意思是:","options":["停泊","(船)倾覆,翻","加速","装载"],"answer_index":1,"explanation_cn":"capsize = (船)倾覆、翻。✓ it capsized and sank."}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l43',10,NULL,'choice','{"stem":"\"The bigger the risk, the ___ the premium.\"(the + 比较级, the + 比较级)","options":["high","highest","higher","more high"],"answer_index":2,"stem_cn":"风险越大,保险费越高。","explanation_cn":"the + 比较级, the + 比较级;后半用 higher。✓ the bigger …, the higher … ✗ high / highest / more high:比较级用 higher。"}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l43',10,NULL,'choice','{"stem":"\"The sides were ___ smooth that no chain would hold.\"(“如此…以至于”,程度副词)","options":["so","such","very","too"],"answer_index":0,"stem_cn":"盘边太光滑,链子挂不住。","explanation_cn":"so + 形容词 + that;smooth 是形容词,用 so。✓ so smooth that … ✗ such(接名词)/ very / too:接形容词接 that 结果用 so。"}'::jsonb,4) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l43',10,NULL,'choice','{"stem":"\"put into operation\" 的意思是:","options":["停止使用","使运转、开动起来","购买","拆卸"],"answer_index":1,"explanation_cn":"put into operation = 使运转、开动起来。✓ a winch was put into operation 绞车开动起来。"}'::jsonb,5) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l43',10,NULL,'choice','{"stem":"\"make a claim for\" 的意思是:","options":["放弃权利","提出批评","表示感谢","要求得到(赔偿)"],"answer_index":3,"explanation_cn":"make a claim for = 要求得到、就…索赔。✓ made a claim for the cost 要求补偿费用。"}'::jsonb,6) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l43',10,NULL,'choice','{"stem":"Why was the pie pan bought by the town?","options":["To bake an enormous pie for the annual fair","To sell it to a museum","To hold a swimming contest","To use it as a boat"],"answer_index":0,"passage":"Insurance companies are normally willing to insure almost anything. Insuring public or private property is standard practice in most parts of the world. If, however, you were holding an outdoor party, you could just as easily insure yourself in the event of bad weather. Needless to say, the bigger the risk an insurance company takes, the higher the premium you will have to pay. It is not unusual to hear that a shipping company has made a claim for the cost of salvaging a sunken ship. But a claim made by a small town to recover the cost of salvaging a sunken pie pan must surely be one of a kind. Admittedly, it was an unusual pie pan, for it was eighteen feet long and six feet wide. It had been purchased by the town so that an enormous pie could be baked for the annual county fair. The fair committee decided that the best way to move the pan would be by canal, so they insured it for the trip. Shortly after it was launched, the committee went off to a local diner to celebrate. Meanwhile, a group of teenagers climbed onto the pan and held a little party of their own. The dancing proved to be more than the pan could bear, for during the party it capsized and sank in seven feet of water. The committee called a local garage owner, who showed up in a tow truck to salvage the pan. Shivering in their wet clothes, the teenagers looked on while three men dove again and again into the water to locate it. They had little difficulty finding it, but hauling it out proved to be a serious problem. The sides of the pan were so smooth that it was almost impossible to attach cables and chains to the rim without denting it. Eventually chains were fixed to one end and a powerful winch was put into operation. The pan rose to the surface and was gently drawn toward the bank. For one agonizing moment it was perched precariously on the edge, but it suddenly overbalanced and slid back into the water. This time the men clamped heavy metal grips to both sides so that they could fasten the chains. The winch was started again, and one of the men fired up the truck. Several minutes later the pan was hauled clear of the surface. Water streamed off its sides in torrents, with such force that it set up a huge wave in the canal. There was a danger that the wave would rebound off the far bank and send the pan plunging in again. Working at tremendous speed, the men managed to get the pan onto dry land before the wave returned.","explanation_cn":"课文说小镇买这盘子是为了在一年一度的县集市上烤一只巨大的馅饼。✓ an enormous pie for the annual county fair."}'::jsonb,7) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l43',10,NULL,'choice','{"stem":"Why was hauling the pan out so difficult?","options":["It was too light to keep still","It was chained to the canal bottom","The water was frozen solid","Its sides were so smooth that chains could hardly grip it"],"answer_index":3,"passage":"Insurance companies are normally willing to insure almost anything. Insuring public or private property is standard practice in most parts of the world. If, however, you were holding an outdoor party, you could just as easily insure yourself in the event of bad weather. Needless to say, the bigger the risk an insurance company takes, the higher the premium you will have to pay. It is not unusual to hear that a shipping company has made a claim for the cost of salvaging a sunken ship. But a claim made by a small town to recover the cost of salvaging a sunken pie pan must surely be one of a kind. Admittedly, it was an unusual pie pan, for it was eighteen feet long and six feet wide. It had been purchased by the town so that an enormous pie could be baked for the annual county fair. The fair committee decided that the best way to move the pan would be by canal, so they insured it for the trip. Shortly after it was launched, the committee went off to a local diner to celebrate. Meanwhile, a group of teenagers climbed onto the pan and held a little party of their own. The dancing proved to be more than the pan could bear, for during the party it capsized and sank in seven feet of water. The committee called a local garage owner, who showed up in a tow truck to salvage the pan. Shivering in their wet clothes, the teenagers looked on while three men dove again and again into the water to locate it. They had little difficulty finding it, but hauling it out proved to be a serious problem. The sides of the pan were so smooth that it was almost impossible to attach cables and chains to the rim without denting it. Eventually chains were fixed to one end and a powerful winch was put into operation. The pan rose to the surface and was gently drawn toward the bank. For one agonizing moment it was perched precariously on the edge, but it suddenly overbalanced and slid back into the water. This time the men clamped heavy metal grips to both sides so that they could fasten the chains. The winch was started again, and one of the men fired up the truck. Several minutes later the pan was hauled clear of the surface. Water streamed off its sides in torrents, with such force that it set up a huge wave in the canal. There was a danger that the wave would rebound off the far bank and send the pan plunging in again. Working at tremendous speed, the men managed to get the pan onto dry land before the wave returned.","explanation_cn":"课文说盘子四边太光滑,几乎无法拴上缆索和链条。✓ sides so smooth that chains slipped."}'::jsonb,8) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l43',10,NULL,'choice','{"stem":"What did the teenagers do while the men worked?","options":["They looked on, shivering in their wet clothes","They helped dive for the pan","They drove the tow truck","They went home at once"],"answer_index":0,"audio":"Insurance companies are normally willing to insure almost anything. Insuring public or private property is standard practice in most parts of the world. If, however, you were holding an outdoor party, you could just as easily insure yourself in the event of bad weather. Needless to say, the bigger the risk an insurance company takes, the higher the premium you will have to pay. It is not unusual to hear that a shipping company has made a claim for the cost of salvaging a sunken ship. But a claim made by a small town to recover the cost of salvaging a sunken pie pan must surely be one of a kind. Admittedly, it was an unusual pie pan, for it was eighteen feet long and six feet wide. It had been purchased by the town so that an enormous pie could be baked for the annual county fair. The fair committee decided that the best way to move the pan would be by canal, so they insured it for the trip. Shortly after it was launched, the committee went off to a local diner to celebrate. Meanwhile, a group of teenagers climbed onto the pan and held a little party of their own. The dancing proved to be more than the pan could bear, for during the party it capsized and sank in seven feet of water. The committee called a local garage owner, who showed up in a tow truck to salvage the pan. Shivering in their wet clothes, the teenagers looked on while three men dove again and again into the water to locate it. They had little difficulty finding it, but hauling it out proved to be a serious problem. The sides of the pan were so smooth that it was almost impossible to attach cables and chains to the rim without denting it. Eventually chains were fixed to one end and a powerful winch was put into operation. The pan rose to the surface and was gently drawn toward the bank. For one agonizing moment it was perched precariously on the edge, but it suddenly overbalanced and slid back into the water. This time the men clamped heavy metal grips to both sides so that they could fasten the chains. The winch was started again, and one of the men fired up the truck. Several minutes later the pan was hauled clear of the surface. Water streamed off its sides in torrents, with such force that it set up a huge wave in the canal. There was a danger that the wave would rebound off the far bank and send the pan plunging in again. Working at tremendous speed, the men managed to get the pan onto dry land before the wave returned.","explanation_cn":"课文说孩子们穿着湿衣服冻得发抖,在一旁看着工人打捞。✓ shivering, the teenagers looked on."}'::jsonb,9) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l43',10,NULL,'choice','{"stem":"What happened when the pan was first drawn to the bank?","options":["It was loaded onto a truck at once","It broke in two","It overbalanced and slid back into the water","It floated away downstream"],"answer_index":2,"audio":"Insurance companies are normally willing to insure almost anything. Insuring public or private property is standard practice in most parts of the world. If, however, you were holding an outdoor party, you could just as easily insure yourself in the event of bad weather. Needless to say, the bigger the risk an insurance company takes, the higher the premium you will have to pay. It is not unusual to hear that a shipping company has made a claim for the cost of salvaging a sunken ship. But a claim made by a small town to recover the cost of salvaging a sunken pie pan must surely be one of a kind. Admittedly, it was an unusual pie pan, for it was eighteen feet long and six feet wide. It had been purchased by the town so that an enormous pie could be baked for the annual county fair. The fair committee decided that the best way to move the pan would be by canal, so they insured it for the trip. Shortly after it was launched, the committee went off to a local diner to celebrate. Meanwhile, a group of teenagers climbed onto the pan and held a little party of their own. The dancing proved to be more than the pan could bear, for during the party it capsized and sank in seven feet of water. The committee called a local garage owner, who showed up in a tow truck to salvage the pan. Shivering in their wet clothes, the teenagers looked on while three men dove again and again into the water to locate it. They had little difficulty finding it, but hauling it out proved to be a serious problem. The sides of the pan were so smooth that it was almost impossible to attach cables and chains to the rim without denting it. Eventually chains were fixed to one end and a powerful winch was put into operation. The pan rose to the surface and was gently drawn toward the bank. For one agonizing moment it was perched precariously on the edge, but it suddenly overbalanced and slid back into the water. This time the men clamped heavy metal grips to both sides so that they could fasten the chains. The winch was started again, and one of the men fired up the truck. Several minutes later the pan was hauled clear of the surface. Water streamed off its sides in torrents, with such force that it set up a huge wave in the canal. There was a danger that the wave would rebound off the far bank and send the pan plunging in again. Working at tremendous speed, the men managed to get the pan onto dry land before the wave returned.","explanation_cn":"课文说盘子拖到岸边时突然失去平衡,又滑回水里。✓ it overbalanced and slid back."}'::jsonb,10) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_lessons (id,book_no,unit_no,lesson_no,title_en,title_cn,grammar_focus,scene,prelisten_question,grammar_card) VALUES ('am3_l44',3,9,44,'Speed and Comfort','又快捷又舒适','nothing can match … for …(没有…比得上;for=就…而论)、部分否定 hardly anyone(几乎没有人)、形式主语 it is + 形容词 + to do sth、prevent/keep sb from doing / take one''s mind off、形容词 + enough to do / however + 主谓(原创承载 NCE3 第三册 L44 考点·无需净化:陆海空旅行方式对比说明文——论证飞机又快又舒适;美式化 airplane/highway/vacation/movie)','出远门的人常常得决定是走陆路、水路,还是坐飞机。几乎没有人能真正喜欢坐几个小时以上的火车。车厢很快就变得又挤又闷,想摆脱旅途的困扰几乎不可能。看书只能解决一部分问题,因为车轮压在铁轨上那单调的咔哒声很快就把你哄睡了。白天,睡意只是断断续续地袭来。到了夜里,你真想睡时,却往往难以入睡。即便你运气够好订到一张卧铺,也会有半宿盯着车顶那盏小蓝灯,或者在查票时摸索着找车票。到站时,你几乎精疲力尽。长途汽车旅行更不舒服,因为几乎没法看书。在州际公路上,你至少能以相当快的速度安全前行,但旅途大部分时间往往都花在服务区很少、车流拥堵的路上。相比之下,渡船和游轮提供了各式各样文明的享受。你可以在宽敞的甲板上舒展双腿,做游戏,结识有趣的人,享用美食——当然,前提总是海面平静。若海面不平静,你又容易晕船,那就没有哪种旅行方式比这更糟了。即便天气理想,坐船也很费时间,很少有人愿意为了海上旅行的乐趣而牺牲假期。飞机素有危险的名声,连老练的旅客都被它吓到。它还有一个缺点:票价昂贵。可就速度和舒适而论,什么也比不上飞机。在三万英尺的高空、云层之上、以每小时五百多英里的速度飞行,是一种令人兴奋的体验。你不必费心去想办法摆脱旅途的困扰,因为飞机很快就把你送到目的地。有几个小时,你可以靠在舒适的座椅里,尽情享受飞行。有些航班上你甚至能看电影、呷一口冷饮。可即便没有这些精致的享受,也有的是让你有事可做的东西。飞机给你一种不寻常、令人叹为观止的世界景象。你毫不费力地翱翔于高山深谷之上,真真切切看清大地的模样。如果地面被遮住看不见,你还能欣赏那绵延数英里、连成一片的云海奇观,而阳光在晴空中灿烂地照耀。飞行如此平稳,没有什么能妨碍你看书或睡觉。无论你打算怎样打发这段时间,有一点是肯定的:你会精神饱满、衣冠齐整地抵达,不必再花好几天从一段漫长疲惫的旅途中缓过来。','{"q":"Listen and answer — Which type of transport does the writer prefer, do you think?","options":["Air travel — for its speed and comfort","Train travel","Car travel","Sea travel"],"answer_index":0}'::jsonb,'{"title":"nothing can match…for / 部分否定 hardly / 形式主语 it / prevent…from doing / enough to do","intro":"①nothing can match … for …:就…而论,没有什么比得上;for 作“就…而论”。②hardly + anyone/any:几乎没有人/几乎没有,本身表否定,后面动词用肯定形式。③it is + 形容词 + to do sth:it 作形式主语,真正主语是后面的不定式:It is impossible to read。④prevent/keep sb from doing:阻止某人做;take one''s mind off sth:把注意力从…移开。⑤形容词/副词 + enough to do:足够…以至于能;however + 主谓:无论怎样。","table":{"headers":["用法","意思","例子"],"rows":[["nothing can match … for …","就…而论没有能比得上的","Nothing can match a plane for speed"],["hardly anyone","几乎没有人(表否定)","Hardly anyone enjoys it"],["it is + 形容词 + to do","做…是…的(形式主语)","It is impossible to read"],["prevent sb from doing","阻止某人做","Nothing prevents you from reading"]]},"specialRules":[{"rule":"hardly 本身已表否定,句中不能再加 not/no/never（× Hardly no one，√ Hardly anyone）。","mark":"hardly anyone"},{"rule":"prevent/stop/keep sb from doing 都用 from + 动名词;不能写成 prevent sb to do。","mark":"prevent … from doing"},{"rule":"美式:airplane(英式 aeroplane)、highway/freeway(英式 motorway)、vacation(英式 holiday)、movie(英式 film)。本课已按美语写。","mark":"airplane / highway"}]}'::jsonb) ON CONFLICT (id) DO UPDATE SET book_no=EXCLUDED.book_no,title_en=EXCLUDED.title_en,title_cn=EXCLUDED.title_cn,grammar_focus=EXCLUDED.grammar_focus,scene=EXCLUDED.scene,prelisten_question=EXCLUDED.prelisten_question,grammar_card=EXCLUDED.grammar_card;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am3_l44',1,NULL,'People traveling long distances often have to decide whether to go by land, sea, or air. Hardly anyone can truly enjoy sitting on a train for more than a few hours. Train compartments soon get cramped and stuffy, and it is almost impossible to take your mind off the journey. Reading is only a partial solution, for the monotonous rhythm of the wheels clicking on the rails soon lulls you to sleep.','出远门的人常常得决定是走陆路、水路,还是坐飞机。几乎没有人能真正喜欢坐几个小时以上的火车。车厢很快就变得又挤又闷,想摆脱旅途的困扰几乎不可能。看书只能解决一部分问题,因为车轮压在铁轨上那单调的咔哒声很快就把你哄睡了。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am3_l44',2,NULL,'During the day, sleep comes in snatches. At night, when you really want to sleep, you rarely manage to. If you are lucky enough to get a sleeper, you spend half the night staring at the small blue light on the ceiling, or fumbling for your ticket when the conductor comes through. Inevitably, you arrive at your destination almost exhausted.','白天,睡意只是断断续续地袭来。到了夜里,你真想睡时,却往往难以入睡。即便你运气够好订到一张卧铺,也会有半宿盯着车顶那盏小蓝灯,或者在查票时摸索着找车票。到站时,你几乎精疲力尽。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am3_l44',3,NULL,'Long car trips are even less pleasant, for it is quite impossible to read. On the interstate you can at least travel fairly safely at high speeds, but more often than not the greater part of the trip is spent on roads with few rest stops and too much traffic. By comparison, ferry rides and cruises offer a great variety of comforts. You can stretch your legs on the spacious decks, play games, meet interesting people, and enjoy good food — always assuming, of course, that the sea is calm.','长途汽车旅行更不舒服,因为几乎没法看书。在州际公路上,你至少能以相当快的速度安全前行,但旅途大部分时间往往都花在服务区很少、车流拥堵的路上。相比之下,渡船和游轮提供了各式各样文明的享受。你可以在宽敞的甲板上舒展双腿,做游戏,结识有趣的人,享用美食——当然,前提总是海面平静。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am3_l44',4,NULL,'If it is not, and you happen to get seasick, no form of travel could be worse. Even in ideal weather, sea journeys take a long time, and relatively few people are willing to sacrifice vacation days for the pleasure of traveling by sea. Airplanes have the reputation of being dangerous, and even seasoned travelers are intimidated by them. They also have the disadvantage of being expensive. But nothing can match them for speed and comfort.','若海面不平静,你又容易晕船,那就没有哪种旅行方式比这更糟了。即便天气理想,坐船也很费时间,很少有人愿意为了海上旅行的乐趣而牺牲假期。飞机素有危险的名声,连老练的旅客都被它吓到。它还有一个缺点:票价昂贵。可就速度和舒适而论,什么也比不上飞机。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am3_l44',5,NULL,'Traveling at a height of 30,000 feet, far above the clouds, and at over 500 miles an hour, is an exhilarating experience. You do not have to invent ways of taking your mind off the journey, for an airplane gets you to your destination quickly. On some flights you can even watch a movie and sip a cold drink, but even when such refinements are not offered, there is plenty to keep you occupied. You soar effortlessly over high mountains and deep valleys, and the flight is so smooth that nothing prevents you from reading or sleeping. However you decide to spend your time, one thing is certain: you will arrive fresh and unwrinkled, and you will not have to spend the next few days recovering from a long and tiring journey.','在三万英尺的高空、云层之上、以每小时五百多英里的速度飞行,是一种令人兴奋的体验。你不必费心去想办法摆脱旅途的困扰,因为飞机很快就把你送到目的地。有些航班上你甚至能看电影、呷一口冷饮,可即便没有这些精致的享受,也有的是让你有事可做的东西。你毫不费力地翱翔于高山深谷之上,飞行如此平稳,没有什么能妨碍你看书或睡觉。无论你打算怎样打发这段时间,有一点是肯定的:你会精神饱满、衣冠齐整地抵达,不必再花好几天从一段漫长疲惫的旅途中缓过来。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
