INSERT INTO public.american_amencontrast (lesson_id,us,uk,note_cn) VALUES ('am3_l44','airplane','aeroplane','飞机;美语 airplane,英式 aeroplane') ON CONFLICT (lesson_id,us) DO UPDATE SET uk=EXCLUDED.uk,note_cn=EXCLUDED.note_cn;
INSERT INTO public.american_amencontrast (lesson_id,us,uk,note_cn) VALUES ('am3_l44','highway','motorway','高速公路;美语 highway/freeway,英式 motorway') ON CONFLICT (lesson_id,us) DO UPDATE SET uk=EXCLUDED.uk,note_cn=EXCLUDED.note_cn;
INSERT INTO public.american_amencontrast (lesson_id,us,uk,note_cn) VALUES ('am3_l44','vacation','holiday','假期;美语 vacation,英式 holiday') ON CONFLICT (lesson_id,us) DO UPDATE SET uk=EXCLUDED.uk,note_cn=EXCLUDED.note_cn;
INSERT INTO public.american_amencontrast (lesson_id,us,uk,note_cn) VALUES ('am3_l44','movie','film','电影;美语 movie,英式 film') ON CONFLICT (lesson_id,us) DO UPDATE SET uk=EXCLUDED.uk,note_cn=EXCLUDED.note_cn;
INSERT INTO public.american_amencontrast (lesson_id,us,uk,note_cn,ipa,example1,example1_cn,example2,example2_cn) VALUES ('am3_l44','take one''s mind off','',NULL,'/teɪk wʌnz maɪnd ɔːf/','You can''t take your mind off a bumpy ride.','颠簸的旅途让你无法转移注意力。','A good book takes your mind off your worries.','一本好书能让你忘掉烦恼。') ON CONFLICT (lesson_id,us) DO UPDATE SET ipa=EXCLUDED.ipa,example1=EXCLUDED.example1,example1_cn=EXCLUDED.example1_cn,example2=EXCLUDED.example2,example2_cn=EXCLUDED.example2_cn;
INSERT INTO public.american_amencontrast (lesson_id,us,uk,note_cn,ipa,example1,example1_cn,example2,example2_cn) VALUES ('am3_l44','more often than not','',NULL,'/mɔːr ˈɔːfən ðæn nɑːt/','More often than not, the roads are crowded.','路上往往很拥挤。','More often than not, he arrives late.','他经常迟到。') ON CONFLICT (lesson_id,us) DO UPDATE SET ipa=EXCLUDED.ipa,example1=EXCLUDED.example1,example1_cn=EXCLUDED.example1_cn,example2=EXCLUDED.example2,example2_cn=EXCLUDED.example2_cn;
INSERT INTO public.american_amencontrast (lesson_id,us,uk,note_cn,ipa,example1,example1_cn,example2,example2_cn) VALUES ('am3_l44','keep sb occupied','',NULL,'/kiːp ˈsʌmbədi ˈɑːkjupaɪd/','There is plenty to keep you occupied.','有很多事让你有事可做。','Toys keep the kids occupied.','玩具让孩子们有事可做。') ON CONFLICT (lesson_id,us) DO UPDATE SET ipa=EXCLUDED.ipa,example1=EXCLUDED.example1,example1_cn=EXCLUDED.example1_cn,example2=EXCLUDED.example2,example2_cn=EXCLUDED.example2_cn;
INSERT INTO public.american_amencontrast (lesson_id,us,uk,note_cn,ipa,example1,example1_cn,example2,example2_cn) VALUES ('am3_l44','settle back','',NULL,'/ˈsetl bæk/','You settle back in a deep seat and relax.','你靠在舒适的座椅里放松。','He settled back and closed his eyes.','他往后一靠,闭上了眼睛。') ON CONFLICT (lesson_id,us) DO UPDATE SET ipa=EXCLUDED.ipa,example1=EXCLUDED.example1,example1_cn=EXCLUDED.example1_cn,example2=EXCLUDED.example2,example2_cn=EXCLUDED.example2_cn;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l44',5,'am3_l44_gp1','choice','{"stem":"\"Nothing can ___ an airplane for speed and comfort.\"(“没有…比得上”,填这个动词)","options":["copy","join","follow","match"],"answer_index":3,"stem_cn":"论速度和舒适,没什么比得上飞机。","explanation_cn":"match sth for …,“就…而论比得上”;nothing can match … 表“没有能比得上的”。✓ Nothing can match a plane for speed. ✗ join 加入;✗ follow 跟随;✗ copy 复制——都不表“比得上”。"}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l44',5,'am3_l44_gp1','choice','{"stem":"\"Nothing can match a plane ___ speed.\"(“就…而论”,match 后填介词)","options":["at","with","for","to"],"answer_index":2,"stem_cn":"就速度而论,没什么比得上飞机。","explanation_cn":"match … for …,for 作“就…而论”。✓ match a plane for speed. ✗ to / with / at:此处固定用 for。"}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l44',5,'am3_l44_gp1','choice','{"stem":"\"For comfort, ___ can match a plane.\"(“没有任何东西能比得上”,填这个词)","options":["nothing","something","anything","everything"],"answer_index":0,"stem_cn":"论舒适,没有任何东西比得上飞机。","explanation_cn":"表“没有任何东西能比得上”,用否定词 nothing 作主语。✓ Nothing can match a plane. ✗ anything / something / everything:此处需否定词 nothing。"}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l44',5,'am3_l44_gp2','choice','{"stem":"\"___ anyone can enjoy a long train ride.\"(“几乎没有人”)","options":["Quite","Hardly","Almost","Nearly"],"answer_index":1,"stem_cn":"几乎没有人能享受长途火车。","explanation_cn":"“几乎没有人”用 hardly anyone;hardly 本身表否定。✓ Hardly anyone can enjoy … ✗ Nearly / Almost / Quite:表“几乎没有”用 hardly。"}'::jsonb,4) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l44',5,'am3_l44_gp2','choice','{"stem":"\"There is ___ any space in a cramped compartment.\"(“几乎没有…”,表否定程度的副词)","options":["hardly","mostly","almost","nearly"],"answer_index":0,"stem_cn":"拥挤的车厢里几乎没有空间。","explanation_cn":"“几乎没有(空间)”用 hardly any;hardly 表否定程度。✓ hardly any space. ✗ nearly / almost / mostly:“几乎没有”用 hardly。"}'::jsonb,5) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l44',5,'am3_l44_gp2','choice','{"stem":"\"Hardly anyone ___ enjoys sitting for hours.\"(hardly 已含否定,后面动词用肯定形式)","options":["hardly","never","not","truly"],"answer_index":3,"stem_cn":"几乎没有人真正喜欢一坐几个钟头。","explanation_cn":"hardly anyone 已含否定,后面动词用肯定形式,不能再加 not/never;填肯定副词 truly。✓ Hardly anyone truly enjoys it. ✗ not / never(双重否定)/ hardly(重复)。"}'::jsonb,6) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l44',5,'am3_l44_gp3','choice','{"stem":"\"It is almost impossible ___ your mind off the journey.\"(it 作形式主语,后接不定式)","options":["taking","to take","took","take"],"answer_index":1,"stem_cn":"要摆脱旅途的困扰几乎不可能。","explanation_cn":"it 作形式主语,真正主语是不定式;It is impossible to take …。✓ It is almost impossible to take your mind off. ✗ taking / take / took:形式主语后接不定式 to take。"}'::jsonb,7) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l44',5,'am3_l44_gp3','choice','{"stem":"\"It is quite impossible ___ in a moving car.\"(形式主语 it + 形容词 + 不定式)","options":["read","reads","reading","to read"],"answer_index":3,"stem_cn":"在行驶的车里看书几乎不可能。","explanation_cn":"形式主语 it + 形容词 + 不定式。✓ It is quite impossible to read. ✗ reading / read / reads:后接不定式 to read。"}'::jsonb,8) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l44',5,'am3_l44_gp3','choice','{"stem":"\"___ is exhilarating to fly above the clouds.\"(形式主语,填做形式主语的那个词)","options":["That","This","It","There"],"answer_index":2,"stem_cn":"在云端飞行令人兴奋。","explanation_cn":"真正主语是后面的不定式 to fly,句首用形式主语 It。✓ It is exhilarating to fly above the clouds. ✗ That / This / There:形式主语用 It。"}'::jsonb,9) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l44',5,'am3_l44_gp4','choice','{"stem":"\"The smooth flight lets nothing prevent you ___ reading.\"(prevent sb ___ doing:阻止某人做)","options":["to","of","for","from"],"answer_index":3,"stem_cn":"平稳的飞行不会妨碍你看书。","explanation_cn":"prevent sb from doing sth,“阻止某人做”;介词用 from。✓ nothing prevents you from reading. ✗ to / of / for:prevent 搭配 from + 动名词。"}'::jsonb,10) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l44',5,'am3_l44_gp4','choice','{"stem":"\"You cannot take your mind ___ a bumpy train ride.\"(take one''s mind ___ sth:把注意力移开)","options":["up","off","on","in"],"answer_index":1,"stem_cn":"颠簸的火车让你无法转移注意力。","explanation_cn":"take one''s mind off sth,“把注意力从…移开”;介词用 off。✓ take your mind off the ride. ✗ on / in / up:固定搭配是 off。"}'::jsonb,11) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l44',5,'am3_l44_gp4','choice','{"stem":"\"There is plenty to keep you ___ on a long flight.\"(keep sb + 过去分词:使…有事可做)","options":["to occupy","occupy","occupying","occupied"],"answer_index":3,"stem_cn":"长途飞行有很多事让你有事可做。","explanation_cn":"keep sb + 过去分词/形容词,“使某人保持…”;keep you occupied=使你有事可做。✓ keep you occupied. ✗ occupy / occupying / to occupy:keep sb 后接过去分词 occupied。"}'::jsonb,12) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l44',5,'am3_l44_gp5','choice','{"stem":"\"If you are lucky ___ to get a sleeper, you can lie down.\"(形容词 + ___ + to do:足够…以至于能)","options":["enough","too","very","so"],"answer_index":0,"stem_cn":"若你运气够好订到卧铺,就能躺下。","explanation_cn":"形容词 + enough + to do,“足够…以至于能”;enough 放形容词之后。✓ lucky enough to get a sleeper. ✗ too(too…to 表否定结果)/ so / very:此处用 enough。"}'::jsonb,13) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l44',5,'am3_l44_gp5','choice','{"stem":"\"The seat is comfortable ___ to sleep in.\"(comfortable + ___ + to do)","options":["too","such","enough","more"],"answer_index":2,"stem_cn":"这座位舒服得能睡着。","explanation_cn":"comfortable enough to sleep in,“舒服得能睡”;enough 后接不定式。✓ comfortable enough to sleep in. ✗ too / more / such:结构是 adj + enough + to do。"}'::jsonb,14) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l44',5,'am3_l44_gp5','choice','{"stem":"\"___ you decide to spend the time, you''ll arrive fresh.\"(“无论你怎样…”,让步)","options":["However","Wherever","Whenever","Whatever"],"answer_index":0,"stem_cn":"无论你怎样打发时间,都会精神饱满地到达。","explanation_cn":"“无论你怎样…”用 however + 主谓,表让步。✓ However you decide to spend your time … ✗ Whatever(接名词/作宾语)/ Whenever(无论何时)/ Wherever(无论何地)。"}'::jsonb,15) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l44',5,'am3_l44_gp6','choice','{"stem":"\"To fly or rise high in the air is to ___.\"(“高飞、翱翔”用哪个词)","options":["sink","crawl","soar","halt"],"answer_index":2,"stem_cn":"在空中高飞、翱翔。","explanation_cn":"在空中高飞、翱翔是 soar。✓ soar effortlessly over mountains. ✗ sink 下沉;✗ crawl 爬行;✗ halt 停止——都不对。"}'::jsonb,16) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l44',5,'am3_l44_gp6','choice','{"stem":"\"A room that is large and roomy is ___.\"(“宽敞的”用哪个词)","options":["narrow","spacious","tiny","cramped"],"answer_index":1,"stem_cn":"又大又宽敞的房间。","explanation_cn":"又大又宽敞是 spacious。✓ the spacious decks. ✗ cramped 窄小;✗ narrow 狭窄;✗ tiny 极小——都相反或不对。"}'::jsonb,17) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l44',5,'am3_l44_gp6','choice','{"stem":"\"Something dull that never changes feels ___.\"(“单调乏味的”用哪个词)","options":["monotonous","varied","exciting","sudden"],"answer_index":0,"stem_cn":"一成不变、枯燥乏味的。","explanation_cn":"一成不变、枯燥乏味是 monotonous。✓ the monotonous rhythm of the wheels. ✗ exciting 令人兴奋;✗ varied 多样;✗ sudden 突然——都不对。"}'::jsonb,18) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l44',6,NULL,'choice','{"stem":"cramped 的意思是:","options":["干净的","宽敞的","窄小的,拥挤的","明亮的"],"answer_index":2,"explanation_cn":"cramped = 窄小的、拥挤的。✓ cramped and stuffy 又挤又闷。"}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l44',6,NULL,'choice','{"stem":"monotonous 的意思是:","options":["单调乏味的","有趣的","短暂的","响亮的"],"answer_index":0,"explanation_cn":"monotonous = 单调乏味的。✓ the monotonous rhythm 单调的节奏。"}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l44',6,NULL,'choice','{"stem":"exhilarating 的意思是:","options":["令人厌烦的","使人高兴的,令人兴奋的","使人疲倦的","令人恐惧的"],"answer_index":1,"explanation_cn":"exhilarating = 使人高兴、令人兴奋的。✓ an exhilarating experience 令人兴奋的体验。"}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l44',6,NULL,'choice','{"stem":"intimidate 的意思是:","options":["欢迎","照顾","鼓励","恐吓,恫吓"],"answer_index":3,"explanation_cn":"intimidate = 恐吓、恫吓。✓ travelers are intimidated by them 旅客被它吓到。"}'::jsonb,4) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l44',6,NULL,'choice','{"stem":"destination 的意思是:","options":["目的地","行李","起点","路线"],"answer_index":0,"explanation_cn":"destination = 目的地。✓ arrive at your destination 到达目的地。"}'::jsonb,5) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l44',6,NULL,'choice','{"stem":"breathtaking 的意思是:","options":["缓慢的","激动人心的,惊人的","平淡无奇的","十分普通的"],"answer_index":1,"explanation_cn":"breathtaking = 激动人心、令人惊叹的。✓ a breathtaking view 令人叹为观止的景象。"}'::jsonb,6) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l44',7,NULL,'cloze','{"stem":"第 1 空","context":"People who travel far must decide whether to go by land, sea, or air. Hardly ___1___ can truly enjoy a long train ride, and it is almost impossible ___2___ your mind off the journey. Sea trips are pleasant but slow. Airplanes are expensive, yet nothing can match them ___3___ speed and comfort. The flight is so smooth that nothing prevents you ___4___ reading or sleeping.","blank_no":1,"options":["anyone","someone","no one","everyone"],"answer_index":0,"explanation_cn":"hardly anyone,“几乎没有人”;hardly 表否定,后接 anyone。✓ Hardly anyone can truly enjoy … ✗ someone / no one(与 hardly 双重否定)/ everyone。"}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET payload=EXCLUDED.payload;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l44',7,NULL,'cloze','{"stem":"第 2 空","context":"People who travel far must decide whether to go by land, sea, or air. Hardly ___1___ can truly enjoy a long train ride, and it is almost impossible ___2___ your mind off the journey. Sea trips are pleasant but slow. Airplanes are expensive, yet nothing can match them ___3___ speed and comfort. The flight is so smooth that nothing prevents you ___4___ reading or sleeping.","blank_no":2,"options":["to take","taking","take","took"],"answer_index":0,"explanation_cn":"it 作形式主语,后接不定式 to take。✓ it is almost impossible to take your mind off. ✗ taking / take / took。"}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET payload=EXCLUDED.payload;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l44',7,NULL,'cloze','{"stem":"第 3 空","context":"People who travel far must decide whether to go by land, sea, or air. Hardly ___1___ can truly enjoy a long train ride, and it is almost impossible ___2___ your mind off the journey. Sea trips are pleasant but slow. Airplanes are expensive, yet nothing can match them ___3___ speed and comfort. The flight is so smooth that nothing prevents you ___4___ reading or sleeping.","blank_no":3,"options":["for","to","with","at"],"answer_index":0,"explanation_cn":"match … for …,for 作“就…而论”。✓ match them for speed and comfort. ✗ to / with / at。"}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET payload=EXCLUDED.payload;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l44',7,NULL,'cloze','{"stem":"第 4 空","context":"People who travel far must decide whether to go by land, sea, or air. Hardly ___1___ can truly enjoy a long train ride, and it is almost impossible ___2___ your mind off the journey. Sea trips are pleasant but slow. Airplanes are expensive, yet nothing can match them ___3___ speed and comfort. The flight is so smooth that nothing prevents you ___4___ reading or sleeping.","blank_no":4,"options":["from","to","of","for"],"answer_index":0,"explanation_cn":"prevent sb from doing,介词 from。✓ prevents you from reading or sleeping. ✗ to / of / for。"}'::jsonb,4) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET payload=EXCLUDED.payload;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l44',8,NULL,'choice','{"stem":"Which type of transport does the writer prefer?","options":["Train travel","Car travel","Air travel (the airplane)","Sea travel"],"answer_index":2,"explanation_cn":"录音说尽管飞机贵,但就速度和舒适而论无可匹敌,作者显然偏爱坐飞机。✓ prefers air travel."}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l44',8,NULL,'choice','{"stem":"Why does the writer dislike long train journeys?","options":["The tickets are too cheap","The trains are too fast","There is no scenery","Compartments get cramped and stuffy, and sleep comes only in snatches"],"answer_index":3,"explanation_cn":"录音说火车车厢又挤又闷,白天睡意断断续续、夜里又难入睡。✓ cramped, stuffy, sleep in snatches."}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l44',8,NULL,'choice','{"stem":"What can spoil a sea journey?","options":["Arriving too early","Getting seasick when the sea is rough","The lack of decks","Too much reading"],"answer_index":1,"explanation_cn":"录音说海面不平静时容易晕船,那样没有哪种旅行更糟。✓ seasick when the sea is rough."}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l44',9,NULL,'choice','{"stem":"你想说\"论速度和舒适,没什么能比得上飞机\"(nothing can match … for …):","options":["Nothing can match to an airplane for speed and comfort.","Nothing can match an airplane of speed and comfort.","Nothing can match an airplane for speed and comfort.","Anything can match an airplane for speed and comfort."],"answer_index":2,"explanation_cn":"match … for …,match 后直接跟名词、再用 for“就…而论”;不用 match to / match of。✓ Nothing can match an airplane for speed and comfort. 场合:强调“没有能比得上的”。"}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l44',9,NULL,'choice','{"stem":"你想说\"几乎没有人喜欢长途火车\"(hardly anyone):","options":["Hardly anyone enjoys a long train ride.","Hardly someone enjoys a long train ride.","Hardly no one enjoys a long train ride.","Hardly anyone doesn''t enjoy a long train ride."],"answer_index":0,"explanation_cn":"hardly 已表否定,句中不能再加 no one/doesn''t;hardly 后接 anyone。✓ Hardly anyone enjoys a long train ride. 场合:表达“几乎没有人…”。"}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l44',9,NULL,'choice','{"stem":"你想说\"平稳的飞行不会妨碍你看书\"(prevent sb from doing):","options":["A smooth flight does not prevent you reading.","A smooth flight does not prevent you for reading.","A smooth flight does not prevent you to read.","A smooth flight does not prevent you from reading."],"answer_index":3,"explanation_cn":"prevent sb from doing,用 from + 动名词;不用 prevent to do / prevent doing / prevent for。✓ does not prevent you from reading. 场合:表达“不妨碍某人做…”。"}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l44',10,NULL,'choice','{"stem":"intimidate 的意思是:","options":["照顾","鼓励","恐吓,恫吓","欢迎"],"answer_index":2,"explanation_cn":"intimidate = 恐吓、恫吓。✓ travelers are intimidated by them."}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l44',10,NULL,'choice','{"stem":"soar 的意思是:","options":["高飞,翱翔","下沉","停止","爬行"],"answer_index":0,"explanation_cn":"soar = 高飞、翱翔。✓ you soar effortlessly over mountains."}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l44',10,NULL,'choice','{"stem":"\"Nothing can ___ an airplane for speed and comfort.\"(“没有…比得上”,填这个动词)","options":["follow","copy","match","join"],"answer_index":2,"stem_cn":"论速度和舒适,没什么比得上飞机。","explanation_cn":"match … for …,“就…而论比得上”。✓ Nothing can match a plane for speed. ✗ join / follow / copy:都不表“比得上”。"}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l44',10,NULL,'choice','{"stem":"\"___ anyone can enjoy a long train ride.\"(“几乎没有人”)","options":["Hardly","Quite","Almost","Nearly"],"answer_index":0,"stem_cn":"几乎没有人能享受长途火车。","explanation_cn":"“几乎没有人”用 hardly anyone,hardly 本身表否定。✓ Hardly anyone can enjoy … ✗ Nearly / Almost / Quite。"}'::jsonb,4) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l44',10,NULL,'choice','{"stem":"\"take one''s mind off\" 的意思是:","options":["下定决心","改变主意","牢记在心","把注意力从…移开"],"answer_index":3,"explanation_cn":"take one''s mind off = 把注意力从…移开。✓ take your mind off the journey 摆脱旅途的困扰。"}'::jsonb,5) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l44',10,NULL,'choice','{"stem":"\"more often than not\" 的意思是:","options":["恰好","往往,经常","从不","偶尔一次"],"answer_index":1,"explanation_cn":"more often than not = 往往、经常。✓ more often than not the roads are crowded."}'::jsonb,6) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l44',10,NULL,'choice','{"stem":"According to the writer, why are long car trips unpleasant?","options":["You cannot read, and much of the trip is on crowded roads with few rest stops","Cars have no seats","You must always drive at night","Cars are too slow"],"answer_index":0,"passage":"People traveling long distances often have to decide whether to go by land, sea, or air. Hardly anyone can truly enjoy sitting on a train for more than a few hours. Train compartments soon get cramped and stuffy, and it is almost impossible to take your mind off the journey. Reading is only a partial solution, for the monotonous rhythm of the wheels clicking on the rails soon lulls you to sleep. During the day, sleep comes in snatches. At night, when you really want to sleep, you rarely manage to. If you are lucky enough to get a sleeper, you spend half the night staring at the small blue light on the ceiling, or fumbling for your ticket when the conductor comes through. Inevitably, you arrive at your destination almost exhausted. Long car trips are even less pleasant, for it is quite impossible to read. On the interstate you can at least travel fairly safely at high speeds, but more often than not the greater part of the trip is spent on roads with few rest stops and too much traffic. By comparison, ferry rides and cruises offer a great variety of comforts. You can stretch your legs on the spacious decks, play games, meet interesting people, and enjoy good food — always assuming, of course, that the sea is calm. If it is not, and you happen to get seasick, no form of travel could be worse. Even in ideal weather, sea journeys take a long time, and relatively few people are willing to sacrifice vacation days for the pleasure of traveling by sea. Airplanes have the reputation of being dangerous, and even seasoned travelers are intimidated by them. They also have the disadvantage of being expensive. But nothing can match them for speed and comfort. Traveling at a height of 30,000 feet, far above the clouds, and at over 500 miles an hour, is an exhilarating experience. You do not have to invent ways of taking your mind off the journey, for an airplane gets you to your destination quickly. For a few hours you settle back in a deep seat and enjoy the flight. On some flights you can even watch a movie and sip a cold drink. But even when such refinements are not offered, there is plenty to keep you occupied. An airplane gives you an unusual and breathtaking view of the world. You soar effortlessly over high mountains and deep valleys, and you really see the shape of the land. If the landscape is hidden, you can enjoy the extraordinary sight of unbroken plains of cloud stretching out for miles, while the sun shines brilliantly in a clear sky. The flight is so smooth that nothing prevents you from reading or sleeping. However you decide to spend your time, one thing is certain: you will arrive fresh and unwrinkled, and you will not have to spend the next few days recovering from a long and tiring journey.","explanation_cn":"课文说长途汽车几乎没法看书,大部分路程又在服务区少、车流拥堵的路上。✓ impossible to read + crowded roads."}'::jsonb,7) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l44',10,NULL,'choice','{"stem":"What does the writer say is the main advantage of airplanes?","options":["They never crash","They serve the best food","Nothing can match them for speed and comfort","They are the cheapest way to travel"],"answer_index":2,"passage":"People traveling long distances often have to decide whether to go by land, sea, or air. Hardly anyone can truly enjoy sitting on a train for more than a few hours. Train compartments soon get cramped and stuffy, and it is almost impossible to take your mind off the journey. Reading is only a partial solution, for the monotonous rhythm of the wheels clicking on the rails soon lulls you to sleep. During the day, sleep comes in snatches. At night, when you really want to sleep, you rarely manage to. If you are lucky enough to get a sleeper, you spend half the night staring at the small blue light on the ceiling, or fumbling for your ticket when the conductor comes through. Inevitably, you arrive at your destination almost exhausted. Long car trips are even less pleasant, for it is quite impossible to read. On the interstate you can at least travel fairly safely at high speeds, but more often than not the greater part of the trip is spent on roads with few rest stops and too much traffic. By comparison, ferry rides and cruises offer a great variety of comforts. You can stretch your legs on the spacious decks, play games, meet interesting people, and enjoy good food — always assuming, of course, that the sea is calm. If it is not, and you happen to get seasick, no form of travel could be worse. Even in ideal weather, sea journeys take a long time, and relatively few people are willing to sacrifice vacation days for the pleasure of traveling by sea. Airplanes have the reputation of being dangerous, and even seasoned travelers are intimidated by them. They also have the disadvantage of being expensive. But nothing can match them for speed and comfort. Traveling at a height of 30,000 feet, far above the clouds, and at over 500 miles an hour, is an exhilarating experience. You do not have to invent ways of taking your mind off the journey, for an airplane gets you to your destination quickly. For a few hours you settle back in a deep seat and enjoy the flight. On some flights you can even watch a movie and sip a cold drink. But even when such refinements are not offered, there is plenty to keep you occupied. An airplane gives you an unusual and breathtaking view of the world. You soar effortlessly over high mountains and deep valleys, and you really see the shape of the land. If the landscape is hidden, you can enjoy the extraordinary sight of unbroken plains of cloud stretching out for miles, while the sun shines brilliantly in a clear sky. The flight is so smooth that nothing prevents you from reading or sleeping. However you decide to spend your time, one thing is certain: you will arrive fresh and unwrinkled, and you will not have to spend the next few days recovering from a long and tiring journey.","explanation_cn":"课文明说飞机虽贵,但就速度和舒适而论无可匹敌。✓ nothing can match them for speed and comfort."}'::jsonb,8) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l44',10,NULL,'choice','{"stem":"What does the writer say about sleep on a night train?","options":["You sleep deeply all night long","At night, when you really want to sleep, you rarely manage to","Trains have no sleepers at all","You are told not to sleep"],"answer_index":1,"audio":"People traveling long distances often have to decide whether to go by land, sea, or air. Hardly anyone can truly enjoy sitting on a train for more than a few hours. Train compartments soon get cramped and stuffy, and it is almost impossible to take your mind off the journey. Reading is only a partial solution, for the monotonous rhythm of the wheels clicking on the rails soon lulls you to sleep. During the day, sleep comes in snatches. At night, when you really want to sleep, you rarely manage to. If you are lucky enough to get a sleeper, you spend half the night staring at the small blue light on the ceiling, or fumbling for your ticket when the conductor comes through. Inevitably, you arrive at your destination almost exhausted. Long car trips are even less pleasant, for it is quite impossible to read. On the interstate you can at least travel fairly safely at high speeds, but more often than not the greater part of the trip is spent on roads with few rest stops and too much traffic. By comparison, ferry rides and cruises offer a great variety of comforts. You can stretch your legs on the spacious decks, play games, meet interesting people, and enjoy good food — always assuming, of course, that the sea is calm. If it is not, and you happen to get seasick, no form of travel could be worse. Even in ideal weather, sea journeys take a long time, and relatively few people are willing to sacrifice vacation days for the pleasure of traveling by sea. Airplanes have the reputation of being dangerous, and even seasoned travelers are intimidated by them. They also have the disadvantage of being expensive. But nothing can match them for speed and comfort. Traveling at a height of 30,000 feet, far above the clouds, and at over 500 miles an hour, is an exhilarating experience. You do not have to invent ways of taking your mind off the journey, for an airplane gets you to your destination quickly. For a few hours you settle back in a deep seat and enjoy the flight. On some flights you can even watch a movie and sip a cold drink. But even when such refinements are not offered, there is plenty to keep you occupied. An airplane gives you an unusual and breathtaking view of the world. You soar effortlessly over high mountains and deep valleys, and you really see the shape of the land. If the landscape is hidden, you can enjoy the extraordinary sight of unbroken plains of cloud stretching out for miles, while the sun shines brilliantly in a clear sky. The flight is so smooth that nothing prevents you from reading or sleeping. However you decide to spend your time, one thing is certain: you will arrive fresh and unwrinkled, and you will not have to spend the next few days recovering from a long and tiring journey.","explanation_cn":"课文说夜里你真想睡时反而往往睡不着。✓ at night you rarely manage to sleep."}'::jsonb,9) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l44',10,NULL,'choice','{"stem":"What breathtaking view can an airplane offer?","options":["Deep underground caves","The ocean floor","Unbroken plains of cloud stretching for miles in a clear sky","City streets seen close up"],"answer_index":2,"audio":"People traveling long distances often have to decide whether to go by land, sea, or air. Hardly anyone can truly enjoy sitting on a train for more than a few hours. Train compartments soon get cramped and stuffy, and it is almost impossible to take your mind off the journey. Reading is only a partial solution, for the monotonous rhythm of the wheels clicking on the rails soon lulls you to sleep. During the day, sleep comes in snatches. At night, when you really want to sleep, you rarely manage to. If you are lucky enough to get a sleeper, you spend half the night staring at the small blue light on the ceiling, or fumbling for your ticket when the conductor comes through. Inevitably, you arrive at your destination almost exhausted. Long car trips are even less pleasant, for it is quite impossible to read. On the interstate you can at least travel fairly safely at high speeds, but more often than not the greater part of the trip is spent on roads with few rest stops and too much traffic. By comparison, ferry rides and cruises offer a great variety of comforts. You can stretch your legs on the spacious decks, play games, meet interesting people, and enjoy good food — always assuming, of course, that the sea is calm. If it is not, and you happen to get seasick, no form of travel could be worse. Even in ideal weather, sea journeys take a long time, and relatively few people are willing to sacrifice vacation days for the pleasure of traveling by sea. Airplanes have the reputation of being dangerous, and even seasoned travelers are intimidated by them. They also have the disadvantage of being expensive. But nothing can match them for speed and comfort. Traveling at a height of 30,000 feet, far above the clouds, and at over 500 miles an hour, is an exhilarating experience. You do not have to invent ways of taking your mind off the journey, for an airplane gets you to your destination quickly. For a few hours you settle back in a deep seat and enjoy the flight. On some flights you can even watch a movie and sip a cold drink. But even when such refinements are not offered, there is plenty to keep you occupied. An airplane gives you an unusual and breathtaking view of the world. You soar effortlessly over high mountains and deep valleys, and you really see the shape of the land. If the landscape is hidden, you can enjoy the extraordinary sight of unbroken plains of cloud stretching out for miles, while the sun shines brilliantly in a clear sky. The flight is so smooth that nothing prevents you from reading or sleeping. However you decide to spend your time, one thing is certain: you will arrive fresh and unwrinkled, and you will not have to spend the next few days recovering from a long and tiring journey.","explanation_cn":"课文说地面被遮时,可见绵延数英里、连成一片的云海,阳光在晴空中灿烂照耀。✓ unbroken plains of cloud."}'::jsonb,10) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_lessons (id,book_no,unit_no,lesson_no,title_en,title_cn,grammar_focus,scene,prelisten_question,grammar_card) VALUES ('am3_l45',3,9,45,'The Power of the Press','新闻报道的威力','虚拟语气(与过去相反 If + had done, would have done)、not only … but (also) …(不但…而且,句首倒装)、同位语从句(the contention/fact + that)、现在分词短语作状语(Acting on …)、be to be done(注定将被…;情态被动 can be abused)(原创承载 NCE3 第三册 L45 考点·无需净化:新闻自由题材——南达科他一贫困家庭因五胞胎一夜成名、沦为商业化牺牲品;本就美国背景,美式化 airplane/attorney)','在民主国家里,任何限制新闻自由的企图都理所当然地受到谴责。然而,这种自由很容易被滥用。关于普通人的报道,往往比政治事件更能吸引公众注意。我们都爱看别人生活的故事,可若是看关于自己的报道,就很难说也一样爱看了。记者秉持事实至上的论点,靠公开别人的私生活细节,能给当事人带来说不尽的痛苦。报纸的影响力如此巨大,以至于它们不但能给普通人的生活带来重大变化,甚至能帮着推翻一个政府。下面这户穷人家一夜之间名利双收的故事,戏剧性地说明了新闻报道的威力。这家人住在南达科他州一个两万三千人的小镇上。父母已有五个孩子,生活是同贫困的一场无休止的搏斗。他们正等着第六个孩子出世,面临着更为严峻的经济难题。若他们只是再添一个孩子,这件事本来根本不会引人注意——他们会继续同厄运搏斗,默默无闻地过下去。可他们却突然成了五胞胎的父母——四女一男——这件事彻底改变了他们的生活。五个孩子出生的第二天,一架飞机飞抵小镇,带来了六十名记者和摄影师。成名快得惊人。电视摄像机和报纸把消息传遍全国。报纸杂志出高价向这家人购买刊登文字和图片的独家权。礼物纷纷涌来,不只来自素不相识的人,还来自想借此为产品打广告的婴儿食品厂和肥皂厂。这家人住的旧农舍,将被一座价值五十万美元的新居所取代。记者不停地要求采访,于是不得不雇律师充当发言人,在记者招待会上代言。五个婴儿还静静地睡在医院育婴室的氧气帐里时,他们的父母已经在为名声付出代价。他们再也不可能过正常的日子了。他们成了商业化的牺牲品,因为他们的名字有了市场价值。这几个孩子不再是家里五个新成员,而是转眼间成了商品。','{"q":"Listen and answer — Does the writer think the parents were lucky or unlucky to gain prosperity this way? Why?","options":["Unlucky — they became victims of commercialization and lost their normal lives","Lucky — they got rich with no downside","Lucky — they enjoyed being famous","The writer gives no opinion"],"answer_index":0}'::jsonb,'{"title":"虚拟语气(与过去相反) / not only…but also / 同位语从句 that / 现在分词作状语 / be to be done","intro":"①与过去事实相反的虚拟语气:If + 主语 + had + 过去分词, 主语 + would/could/might + have + 过去分词:If they had had one more child, the fact would have passed unnoticed。②not only … but (also) …:不但…而且;not only 放句首时,其后要部分倒装:Not only did they …, but they also …。③同位语从句:抽象名词(contention/fact/belief)后接 that + 完整句,说明其内容。④现在分词短语作状语:Acting on the contention …, reporters …。⑤be to be done:注定/按计划将被…;can be abused:情态动词后接被动。","table":{"headers":["用法","意思","例子"],"rows":[["If had done, would have done","与过去相反的虚拟","If they had had …, it would have passed"],["not only … but (also)","不但…而且","not only change lives but overthrow …"],["the + 抽象名词 + that 从句","同位语从句","the contention that facts are sacred"],["be to be done / can be done","注定被… / 能被…","was to be replaced; can be abused"]]},"specialRules":[{"rule":"与过去相反的虚拟:if 从句必须用 had + 过去分词,主句必须用 would/could/might + have + 过去分词,两半不能都用 would。","mark":"had done … would have done"},{"rule":"not only 位于句首时其所在分句要部分倒装(把助动词提前):Not only did they become famous, but …。","mark":"Not only did …"},{"rule":"美式:airplane(英式 aeroplane)、attorney/lawyer(英式 solicitor)。本课本就美国背景(南达科他州)。","mark":"airplane / attorney"}]}'::jsonb) ON CONFLICT (id) DO UPDATE SET book_no=EXCLUDED.book_no,title_en=EXCLUDED.title_en,title_cn=EXCLUDED.title_cn,grammar_focus=EXCLUDED.grammar_focus,scene=EXCLUDED.scene,prelisten_question=EXCLUDED.prelisten_question,grammar_card=EXCLUDED.grammar_card;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am3_l45',1,NULL,'In democratic countries, any attempt to restrict the freedom of the press is rightly condemned. However, this freedom can easily be abused. Stories about people often attract far more public attention than political events. Though we may enjoy reading about the lives of others, it is extremely doubtful whether we would enjoy reading about ourselves.','在民主国家里,任何限制新闻自由的企图都理所当然地受到谴责。然而,这种自由很容易被滥用。关于普通人的报道,往往比政治事件更能吸引公众注意。我们都爱看别人生活的故事,可若是看关于自己的报道,就很难说也一样爱看了。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am3_l45',2,NULL,'Acting on the contention that facts are sacred, reporters can cause untold suffering to individuals by publishing details about their private lives. Newspapers exert such tremendous influence that they can not only bring about major changes in the lives of ordinary people but can even help overthrow a government. The story of a poor family that acquired fame and fortune overnight dramatically illustrates the power of the press.','记者秉持事实至上的论点,靠公开别人的私生活细节,能给当事人带来说不尽的痛苦。报纸的影响力如此巨大,以至于它们不但能给普通人的生活带来重大变化,甚至能帮着推翻一个政府。下面这户穷人家一夜之间名利双收的故事,戏剧性地说明了新闻报道的威力。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am3_l45',3,NULL,'The family lived in a small town of twenty-three thousand people in South Dakota. As the parents already had five children, life was a perpetual struggle against poverty. They were expecting their sixth child and faced even more pressing money problems. If they had only had one more child, the fact would have passed unnoticed. They would have gone on struggling against economic odds and would have lived in obscurity.','这家人住在南达科他州一个两万三千人的小镇上。父母已有五个孩子,生活是同贫困的一场无休止的搏斗。他们正等着第六个孩子出世,面临着更为严峻的经济难题。若他们只是再添一个孩子,这件事本来根本不会引人注意——他们会继续同厄运搏斗,默默无闻地过下去。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am3_l45',4,NULL,'But they suddenly became the parents of quintuplets — four girls and a boy — an event that radically changed their lives. The day after the birth of the five children, an airplane arrived in town carrying sixty reporters and photographers. The rise to fame was swift. Television cameras and newspapers carried the news to everyone in the country. Newspapers and magazines offered the family huge sums for the exclusive rights to publish stories and photographs.','可他们却突然成了五胞胎的父母——四女一男——这件事彻底改变了他们的生活。五个孩子出生的第二天,一架飞机飞抵小镇,带来了六十名记者和摄影师。成名快得惊人。电视摄像机和报纸把消息传遍全国。报纸杂志出高价向这家人购买刊登文字和图片的独家权。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am3_l45',5,NULL,'Gifts poured in, not only from strangers but from baby-food and soap companies that wanted to advertise their products. The old farmhouse the family lived in was to be replaced by a new five-hundred-thousand-dollar home. Reporters kept pressing for interviews, so lawyers had to be hired to act as spokesmen at press conferences. While the five babies were still sleeping quietly in oxygen tents in a hospital nursery, their parents were already paying the price of fame. They had become the victims of commercialization, for their names had acquired a market value. Instead of being five new members of a family, these children had instantly become a commodity.','礼物纷纷涌来,不只来自素不相识的人,还来自想借此为产品打广告的婴儿食品厂和肥皂厂。这家人住的旧农舍,将被一座价值五十万美元的新居所取代。记者不停地要求采访,于是不得不雇律师充当发言人,在记者招待会上代言。五个婴儿还静静地睡在医院育婴室的氧气帐里时,他们的父母已经在为名声付出代价。他们成了商业化的牺牲品,因为他们的名字有了市场价值。这几个孩子不再是家里五个新成员,而是转眼间成了商品。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_words (lesson_id,word,ipa,pos,meaning_cn,example) VALUES ('am3_l45','democratic','/ˌdeməˈkrætɪk/','adj','民主的','in democratic countries') ON CONFLICT (lesson_id,word) DO UPDATE SET ipa=EXCLUDED.ipa,pos=EXCLUDED.pos,meaning_cn=EXCLUDED.meaning_cn,example=EXCLUDED.example;
