INSERT INTO public.american_amencontrast (lesson_id,us,uk,note_cn) VALUES ('am3_l45','attorney','solicitor','律师;美语常说 attorney/lawyer,英式说 solicitor') ON CONFLICT (lesson_id,us) DO UPDATE SET uk=EXCLUDED.uk,note_cn=EXCLUDED.note_cn;
INSERT INTO public.american_amencontrast (lesson_id,us,uk,note_cn) VALUES ('am3_l45','TV','telly','电视;美语口语 TV,英式口语 telly') ON CONFLICT (lesson_id,us) DO UPDATE SET uk=EXCLUDED.uk,note_cn=EXCLUDED.note_cn;
