INSERT INTO public.american_amencontrast (lesson_id,us,uk,note_cn,ipa,example1,example1_cn,example2,example2_cn) VALUES ('am3_l45','bring about','',NULL,'/brɪŋ əˈbaʊt/','Newspapers can bring about major changes.','报纸能带来重大变化。','The reform brought about big improvements.','这项改革带来了很大改善。') ON CONFLICT (lesson_id,us) DO UPDATE SET ipa=EXCLUDED.ipa,example1=EXCLUDED.example1,example1_cn=EXCLUDED.example1_cn,example2=EXCLUDED.example2,example2_cn=EXCLUDED.example2_cn;
INSERT INTO public.american_amencontrast (lesson_id,us,uk,note_cn,ipa,example1,example1_cn,example2,example2_cn) VALUES ('am3_l45','act on','',NULL,'/ækt ɑːn/','Reporters act on the contention that facts are sacred.','记者按事实至上的论点行事。','The police acted on a tip.','警方根据一条线报采取了行动。') ON CONFLICT (lesson_id,us) DO UPDATE SET ipa=EXCLUDED.ipa,example1=EXCLUDED.example1,example1_cn=EXCLUDED.example1_cn,example2=EXCLUDED.example2,example2_cn=EXCLUDED.example2_cn;
INSERT INTO public.american_amencontrast (lesson_id,us,uk,note_cn,ipa,example1,example1_cn,example2,example2_cn) VALUES ('am3_l45','pour in','',NULL,'/pɔːr ɪn/','Gifts poured in from strangers.','礼物从陌生人那里纷纷涌来。','Letters poured in after the show.','节目播出后信件大量涌来。') ON CONFLICT (lesson_id,us) DO UPDATE SET ipa=EXCLUDED.ipa,example1=EXCLUDED.example1,example1_cn=EXCLUDED.example1_cn,example2=EXCLUDED.example2,example2_cn=EXCLUDED.example2_cn;
INSERT INTO public.american_amencontrast (lesson_id,us,uk,note_cn,ipa,example1,example1_cn,example2,example2_cn) VALUES ('am3_l45','press for','',NULL,'/pres fɔːr/','Reporters kept pressing for interviews.','记者不停地要求采访。','The workers pressed for higher pay.','工人们迫切要求加薪。') ON CONFLICT (lesson_id,us) DO UPDATE SET ipa=EXCLUDED.ipa,example1=EXCLUDED.example1,example1_cn=EXCLUDED.example1_cn,example2=EXCLUDED.example2,example2_cn=EXCLUDED.example2_cn;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l45',5,'am3_l45_gp1','choice','{"stem":"\"If they had had one more child, the fact ___ passed unnoticed.\"(与过去相反:主句用 ___ + 过去分词)","options":["would have","would","will have","had"],"answer_index":0,"stem_cn":"若他们只添一个孩子,这事本来不会引人注意。","explanation_cn":"与过去事实相反的虚拟语气,主句用 would + have + 过去分词。✓ the fact would have passed unnoticed. ✗ would(缺 have)/ will have(不用于过去虚拟)/ had:主句用 would have。"}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l45',5,'am3_l45_gp1','choice','{"stem":"\"If the parents had had a sixth child, no one ___ have noticed.\"(与过去相反,主句缺的那个助动词)","options":["will","does","would","had"],"answer_index":2,"stem_cn":"若父母只生第六个孩子,没人会注意。","explanation_cn":"主句与过去相反用 would have + 过去分词;此处 have 已给出,填 would。✓ no one would have noticed. ✗ will / does / had:与过去相反的主句用 would。"}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l45',5,'am3_l45_gp1','choice','{"stem":"\"They would have lived in obscurity if fame ___ come.\"(与过去相反,if 从句用过去完成的否定)","options":["did not","had not","has not","would not"],"answer_index":1,"stem_cn":"若名声没有降临,他们本会默默无闻地生活。","explanation_cn":"与过去相反,if 从句用 had + 过去分词,否定为 had not。✓ if fame had not come. ✗ did not / has not:过去虚拟条件用 had + 过去分词;✗ would not:if 从句里不用 would。"}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l45',5,'am3_l45_gp2','choice','{"stem":"\"Newspapers can not only change lives ___ even overthrow a government.\"(not only … ___ …:不但…而且)","options":["nor","and","but","or"],"answer_index":2,"stem_cn":"报纸不但能改变生活,甚至能推翻政府。","explanation_cn":"not only … but (also) …,“不但…而且”;连接词用 but。✓ not only change lives but even overthrow … ✗ and / or / nor:固定搭配是 not only … but。"}'::jsonb,4) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l45',5,'am3_l45_gp2','choice','{"stem":"\"The press not only informs us ___ also shapes our views.\"(not only … ___ also …)","options":["but","yet","for","so"],"answer_index":0,"stem_cn":"新闻界不但告知我们,还塑造我们的观点。","explanation_cn":"not only … but also …;此处填 but,与后面 also 搭配。✓ not only informs us but also shapes our views. ✗ so / for / yet:与 not only 搭配的是 but。"}'::jsonb,5) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l45',5,'am3_l45_gp2','choice','{"stem":"\"Not only ___ the parents become famous, but they also grew rich.\"(Not only 置句首,后半部分倒装,填助动词)","options":["do","had","were","did"],"answer_index":3,"stem_cn":"父母不但出了名,还发了财。","explanation_cn":"not only 位于句首时,其分句要部分倒装,把助动词提到主语前;实义动词 become 用过去,助动词用 did。✓ Not only did the parents become famous … ✗ were(become 不用 be 助动)/ do(时态错)/ had(此处非完成时)。"}'::jsonb,6) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l45',5,'am3_l45_gp3','choice','{"stem":"\"Reporters act on the contention ___ facts are sacred.\"(同位语从句,说明 contention 内容)","options":["that","whether","what","which"],"answer_index":0,"stem_cn":"记者按事实至上的论点行事。","explanation_cn":"同位语从句说明抽象名词 contention 的内容,引导词用 that(只起连接作用,不作成分)。✓ the contention that facts are sacred. ✗ which / what(要在从句中作成分)/ whether(表“是否”不合意)。"}'::jsonb,7) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l45',5,'am3_l45_gp3','choice','{"stem":"\"The fact ___ they had five children was well known.\"(同位语从句,说明 fact)","options":["it","which","that","what"],"answer_index":2,"stem_cn":"他们有五个孩子这一事实众所周知。","explanation_cn":"同位语从句说明 fact 的内容,用 that。✓ the fact that they had five children. ✗ which / what / it:同位语从句用 that。"}'::jsonb,8) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l45',5,'am3_l45_gp3','choice','{"stem":"\"News spread of the belief ___ the babies were a miracle.\"(同位语从句,说明 belief)","options":["whether","that","which","what"],"answer_index":1,"stem_cn":"婴儿是奇迹这一说法传开了。","explanation_cn":"同位语从句说明 belief 的内容,用 that。✓ the belief that the babies were a miracle. ✗ which / what / whether:说明性内容用 that。"}'::jsonb,9) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l45',5,'am3_l45_gp4','choice','{"stem":"\"___ on the contention that facts are sacred, reporters print anything.\"(现在分词短语作状语:依据…)","options":["Acting","Act","Acted","To act"],"answer_index":0,"stem_cn":"记者以事实至上为依据,什么都敢登。","explanation_cn":"现在分词短语作状语,说明主语 reporters 的依据/方式;主语主动,用现在分词 Acting。✓ Acting on the contention …, reporters print anything. ✗ Act / Acted / To act:作状语的主动分词用 -ing。"}'::jsonb,10) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l45',5,'am3_l45_gp4','choice','{"stem":"\"Gifts poured in, ___ from unknown people.\"(现在分词表伴随:来自…)","options":["came","to come","coming","come"],"answer_index":2,"stem_cn":"礼物涌来,来自陌生人。","explanation_cn":"现在分词表伴随“来自…”;与主语 gifts 同时,用 coming。✓ Gifts poured in, coming from unknown people. ✗ come / came / to come:伴随用 -ing。"}'::jsonb,11) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l45',5,'am3_l45_gp4','choice','{"stem":"\"The plane landed, ___ sixty reporters to the town.\"(现在分词表伴随:带来)","options":["bringing","brought","bring","to bring"],"answer_index":0,"stem_cn":"飞机降落,带来六十名记者。","explanation_cn":"现在分词表伴随“带来”;与主语 plane 主动同时,用 bringing。✓ The plane landed, bringing sixty reporters. ✗ brought / bring / to bring:主动伴随用 -ing。"}'::jsonb,12) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l45',5,'am3_l45_gp5','choice','{"stem":"\"The old farmhouse ___ to be replaced by a new home.\"(be to be done:注定将被…,填 be 动词的过去式)","options":["is","was","has","did"],"answer_index":1,"stem_cn":"那座旧农舍将被一座新居所取代。","explanation_cn":"be to be done 表“注定/按计划将被…”;句子讲过去,be 动词用 was。✓ The farmhouse was to be replaced. ✗ is(时态错)/ has / did:此处 be 动词用过去式 was。"}'::jsonb,13) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l45',5,'am3_l45_gp5','choice','{"stem":"\"Lawyers had to ___ hired to speak for the family.\"(had to 后面接被动语态,不得不被雇)","options":["being","been","be","was"],"answer_index":2,"stem_cn":"不得不雇律师为这家人代言。","explanation_cn":"had to 后接动词原形;此处是被动“不得不被雇”,用 be + 过去分词。✓ Lawyers had to be hired. ✗ been / being / was:had to 后用原形 be。"}'::jsonb,14) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l45',5,'am3_l45_gp5','choice','{"stem":"\"This freedom can easily ___ abused.\"(can 后接被动语态,“能被滥用”)","options":["been","be","being","is"],"answer_index":1,"stem_cn":"这种自由很容易被滥用。","explanation_cn":"can 等情态动词后接原形;被动为 be + 过去分词。✓ this freedom can easily be abused. ✗ been / being / is:情态动词后用原形 be。"}'::jsonb,15) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l45',5,'am3_l45_gp6','choice','{"stem":"\"To limit or keep something within bounds is to ___ it.\"(“限制”用哪个词)","options":["allow","expand","restrict","ignore"],"answer_index":2,"stem_cn":"把某物限制在范围内。","explanation_cn":"把某事物限制在范围内是 restrict。✓ restrict the freedom of the press. ✗ expand 扩大;✗ allow 允许;✗ ignore 忽视——都不对。"}'::jsonb,16) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l45',5,'am3_l45_gp6','choice','{"stem":"\"Something that never ends or is constant is ___.\"(“永久的、无休止的”用哪个词)","options":["brief","rare","sudden","perpetual"],"answer_index":3,"stem_cn":"永不停止、持续不断的。","explanation_cn":"永不停止、持续不断是 perpetual。✓ a perpetual struggle against poverty. ✗ brief 短暂;✗ sudden 突然;✗ rare 稀少——都不对。"}'::jsonb,17) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l45',5,'am3_l45_gp6','choice','{"stem":"\"To use a right wrongly or misuse it is to ___ it.\"(“滥用”用哪个词)","options":["praise","protect","abuse","obey"],"answer_index":2,"stem_cn":"错误地使用、滥用某种权利。","explanation_cn":"错误地使用、滥用权利是 abuse。✓ this freedom can be abused. ✗ protect 保护;✗ obey 遵守;✗ praise 赞美——都不对。"}'::jsonb,18) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l45',6,NULL,'choice','{"stem":"restrict 的意思是:","options":["允许","忽视","扩大","限制"],"answer_index":3,"explanation_cn":"restrict = 限制。✓ restrict the freedom of the press 限制新闻自由。"}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l45',6,NULL,'choice','{"stem":"abuse 的意思是:","options":["遵守","保护","滥用","赞美"],"answer_index":2,"explanation_cn":"abuse = 滥用。✓ this freedom can be abused 这种自由会被滥用。"}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l45',6,NULL,'choice','{"stem":"perpetual 的意思是:","options":["短暂的","临时的","偶然的","永久的,无休止的"],"answer_index":3,"explanation_cn":"perpetual = 永久的、无休止的。✓ a perpetual struggle 无休止的搏斗。"}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l45',6,NULL,'choice','{"stem":"obscurity 的意思是:","options":["权力","默默无闻","名声","财富"],"answer_index":1,"explanation_cn":"obscurity = 默默无闻。✓ live in obscurity 默默无闻地生活。"}'::jsonb,4) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l45',6,NULL,'choice','{"stem":"exclusive 的意思是:","options":["独占的,独家的","免费的","公开的","共享的"],"answer_index":0,"explanation_cn":"exclusive = 独占的、独家的。✓ the exclusive rights to publish 独家刊登权。"}'::jsonb,5) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l45',6,NULL,'choice','{"stem":"commodity 的意思是:","options":["工厂","商品","礼物","服务"],"answer_index":1,"explanation_cn":"commodity = 商品。✓ the children became a commodity 孩子成了商品。"}'::jsonb,6) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l45',7,NULL,'cloze','{"stem":"第 1 空","context":"In democratic countries, any attempt to restrict the freedom of the press is rightly condemned, yet this freedom can easily ___1___ abused. One poor family in South Dakota became famous overnight when quintuplets were born. If they had only had one more child, the fact ___2___ have passed unnoticed. Instead, newspapers not only reported the story ___3___ paid huge sums for exclusive rights. Acting ___4___ the contention that facts are sacred, reporters printed every detail.","blank_no":1,"options":["be","been","being","is"],"answer_index":0,"explanation_cn":"情态动词 can 后接原形;被动用 be + 过去分词。✓ this freedom can easily be abused."}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET payload=EXCLUDED.payload;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l45',7,NULL,'cloze','{"stem":"第 2 空","context":"In democratic countries, any attempt to restrict the freedom of the press is rightly condemned, yet this freedom can easily ___1___ abused. One poor family in South Dakota became famous overnight when quintuplets were born. If they had only had one more child, the fact ___2___ have passed unnoticed. Instead, newspapers not only reported the story ___3___ paid huge sums for exclusive rights. Acting ___4___ the contention that facts are sacred, reporters printed every detail.","blank_no":2,"options":["would","will","does","had"],"answer_index":0,"explanation_cn":"与过去相反的虚拟主句用 would have + 过去分词;have 已给出,填 would。✓ the fact would have passed unnoticed."}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET payload=EXCLUDED.payload;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l45',7,NULL,'cloze','{"stem":"第 3 空","context":"In democratic countries, any attempt to restrict the freedom of the press is rightly condemned, yet this freedom can easily ___1___ abused. One poor family in South Dakota became famous overnight when quintuplets were born. If they had only had one more child, the fact ___2___ have passed unnoticed. Instead, newspapers not only reported the story ___3___ paid huge sums for exclusive rights. Acting ___4___ the contention that facts are sacred, reporters printed every detail.","blank_no":3,"options":["but","and","or","so"],"answer_index":0,"explanation_cn":"not only … but …,“不但…而且”。✓ not only reported the story but paid huge sums."}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET payload=EXCLUDED.payload;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l45',7,NULL,'cloze','{"stem":"第 4 空","context":"In democratic countries, any attempt to restrict the freedom of the press is rightly condemned, yet this freedom can easily ___1___ abused. One poor family in South Dakota became famous overnight when quintuplets were born. If they had only had one more child, the fact ___2___ have passed unnoticed. Instead, newspapers not only reported the story ___3___ paid huge sums for exclusive rights. Acting ___4___ the contention that facts are sacred, reporters printed every detail.","blank_no":4,"options":["on","in","at","of"],"answer_index":0,"explanation_cn":"act on sth,“根据…行动”;固定介词 on。✓ Acting on the contention that facts are sacred."}'::jsonb,4) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET payload=EXCLUDED.payload;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l45',8,NULL,'choice','{"stem":"Does the writer think the parents were lucky to gain wealth this way?","options":["Yes — they were very fortunate","The writer does not say","Yes — they enjoyed the fame","No — they became victims of commercialization"],"answer_index":3,"explanation_cn":"录音说父母沦为商业化的牺牲品、再也无法过正常生活,作者认为他们并不幸运。✓ victims of commercialization."}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l45',8,NULL,'choice','{"stem":"How did the family suddenly become famous?","options":["They won a lottery","They became the parents of quintuplets","They wrote a best-selling book","They found gold"],"answer_index":1,"explanation_cn":"录音说这家人突然生了五胞胎(四女一男),因而一夜成名。✓ became the parents of quintuplets."}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l45',8,NULL,'choice','{"stem":"Why were lawyers hired for the family?","options":["To act as spokesmen at press conferences","To sue the newspapers","To buy a new house","To adopt the babies"],"answer_index":0,"explanation_cn":"录音说记者不停要采访,只好雇律师在记者招待会上代言。✓ lawyers as spokesmen."}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l45',9,NULL,'choice','{"stem":"你想说\"若他们只添一个孩子,这事本来不会引人注意\"(虚拟与过去相反):","options":["If they had had one more child, the fact would have passed unnoticed.","If they have had one more child, the fact would have passed unnoticed.","If they had one more child, the fact would have passed unnoticed.","If they had had one more child, the fact would passed unnoticed."],"answer_index":0,"explanation_cn":"与过去相反:if 从句用 had + 过去分词(had had),主句用 would have + 过去分词;两半不能都用 would,also 主句 have 不能省。✓ If they had had …, the fact would have passed unnoticed. 场合:表达“若当时…,本来会…”。"}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l45',9,NULL,'choice','{"stem":"你想说\"报纸不但能改变生活,甚至能推翻政府\"(not only … but …):","options":["Newspapers can not only change lives but even overthrows a government.","Newspapers not only can change lives but even can overthrows a government.","Newspapers can not only change lives but even overthrow a government.","Newspapers can not only change lives and even overthrow a government."],"answer_index":2,"explanation_cn":"not only … but …,连接词用 but 不用 and;overthrow 与 change 并列,用原形。✓ not only change lives but even overthrow a government. 场合:表达“不但…而且…”。"}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l45',9,NULL,'choice','{"stem":"你想说\"记者按事实至上的论点行事\"(同位语从句 the contention that):","options":["Reporters act on the contention that facts sacred.","Reporters act on the contention which facts are sacred.","Reporters act on the contention what facts are sacred.","Reporters act on the contention that facts are sacred."],"answer_index":3,"explanation_cn":"同位语从句说明 contention 内容,用 that;从句要完整(facts are sacred),不能少 are。✓ the contention that facts are sacred. 场合:用抽象名词 + that 说明内容。"}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l45',10,NULL,'choice','{"stem":"restrict 的意思是:","options":["允许","限制","忽视","扩大"],"answer_index":1,"explanation_cn":"restrict = 限制。✓ restrict the freedom of the press."}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l45',10,NULL,'choice','{"stem":"commodity 的意思是:","options":["商品","礼物","服务","工厂"],"answer_index":0,"explanation_cn":"commodity = 商品。✓ the children became a commodity."}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l45',10,NULL,'choice','{"stem":"\"If they had had one more child, the fact ___ passed unnoticed.\"(与过去相反:主句用 ___ + 过去分词)","options":["will have","would have","had","would"],"answer_index":1,"stem_cn":"若他们只添一个孩子,这事本来不会引人注意。","explanation_cn":"与过去相反,主句用 would have + 过去分词。✓ the fact would have passed unnoticed. ✗ would(缺 have)/ will have / had。"}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l45',10,NULL,'choice','{"stem":"\"Newspapers can not only change lives ___ even overthrow a government.\"(not only … ___ …)","options":["and","nor","but","or"],"answer_index":2,"stem_cn":"报纸不但能改变生活,甚至能推翻政府。","explanation_cn":"not only … but …,“不但…而且”。✓ not only change lives but even overthrow … ✗ and / or / nor。"}'::jsonb,4) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l45',10,NULL,'choice','{"stem":"\"bring about\" 的意思是:","options":["带来、导致","拿走","拒绝","推迟"],"answer_index":0,"explanation_cn":"bring about = 带来、导致。✓ bring about major changes 带来重大变化。"}'::jsonb,5) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l45',10,NULL,'choice','{"stem":"\"pour in\" 的意思是:","options":["慢慢流出","大量涌入、源源而来","停止","倒空"],"answer_index":1,"explanation_cn":"pour in = 大量涌入、源源而来。✓ Gifts poured in 礼物纷纷涌来。"}'::jsonb,6) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l45',10,NULL,'choice','{"stem":"Why does the writer say the family became ''victims of commercialization''?","options":["They were attacked by reporters","They lost all their money","Their names had acquired a market value and the children became a commodity","They were forced to move away"],"answer_index":2,"passage":"In democratic countries, any attempt to restrict the freedom of the press is rightly condemned. However, this freedom can easily be abused. Stories about people often attract far more public attention than political events. Though we may enjoy reading about the lives of others, it is extremely doubtful whether we would enjoy reading about ourselves. Acting on the contention that facts are sacred, reporters can cause untold suffering to individuals by publishing details about their private lives. Newspapers exert such tremendous influence that they can not only bring about major changes in the lives of ordinary people but can even help overthrow a government. The story of a poor family that acquired fame and fortune overnight dramatically illustrates the power of the press. The family lived in a small town of twenty-three thousand people in South Dakota. As the parents already had five children, life was a perpetual struggle against poverty. They were expecting their sixth child and faced even more pressing money problems. If they had only had one more child, the fact would have passed unnoticed. They would have gone on struggling against economic odds and would have lived in obscurity. But they suddenly became the parents of quintuplets — four girls and a boy — an event that radically changed their lives. The day after the birth of the five children, an airplane arrived in town carrying sixty reporters and photographers. The rise to fame was swift. Television cameras and newspapers carried the news to everyone in the country. Newspapers and magazines offered the family huge sums for the exclusive rights to publish stories and photographs. Gifts poured in, not only from strangers but from baby-food and soap companies that wanted to advertise their products. The old farmhouse the family lived in was to be replaced by a new five-hundred-thousand-dollar home. Reporters kept pressing for interviews, so lawyers had to be hired to act as spokesmen at press conferences. While the five babies were still sleeping quietly in oxygen tents in a hospital nursery, their parents were already paying the price of fame. It would never again be possible for them to lead normal lives. They had become the victims of commercialization, for their names had acquired a market value. Instead of being five new members of a family, these children had instantly become a commodity.","explanation_cn":"课文说他们的名字有了市场价值,孩子转眼成了商品,故称商业化的牺牲品。✓ names acquired a market value; a commodity."}'::jsonb,7) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l45',10,NULL,'choice','{"stem":"What would have happened if the parents had had only one more child?","options":["They would have become even more famous","The fact would have passed unnoticed and they would have lived in obscurity","They would have received even more gifts","They would have moved to a big city"],"answer_index":1,"passage":"In democratic countries, any attempt to restrict the freedom of the press is rightly condemned. However, this freedom can easily be abused. Stories about people often attract far more public attention than political events. Though we may enjoy reading about the lives of others, it is extremely doubtful whether we would enjoy reading about ourselves. Acting on the contention that facts are sacred, reporters can cause untold suffering to individuals by publishing details about their private lives. Newspapers exert such tremendous influence that they can not only bring about major changes in the lives of ordinary people but can even help overthrow a government. The story of a poor family that acquired fame and fortune overnight dramatically illustrates the power of the press. The family lived in a small town of twenty-three thousand people in South Dakota. As the parents already had five children, life was a perpetual struggle against poverty. They were expecting their sixth child and faced even more pressing money problems. If they had only had one more child, the fact would have passed unnoticed. They would have gone on struggling against economic odds and would have lived in obscurity. But they suddenly became the parents of quintuplets — four girls and a boy — an event that radically changed their lives. The day after the birth of the five children, an airplane arrived in town carrying sixty reporters and photographers. The rise to fame was swift. Television cameras and newspapers carried the news to everyone in the country. Newspapers and magazines offered the family huge sums for the exclusive rights to publish stories and photographs. Gifts poured in, not only from strangers but from baby-food and soap companies that wanted to advertise their products. The old farmhouse the family lived in was to be replaced by a new five-hundred-thousand-dollar home. Reporters kept pressing for interviews, so lawyers had to be hired to act as spokesmen at press conferences. While the five babies were still sleeping quietly in oxygen tents in a hospital nursery, their parents were already paying the price of fame. It would never again be possible for them to lead normal lives. They had become the victims of commercialization, for their names had acquired a market value. Instead of being five new members of a family, these children had instantly become a commodity.","explanation_cn":"课文说若只多添一个孩子,这事不会引人注意,他们本会默默无闻。✓ passed unnoticed; lived in obscurity."}'::jsonb,8) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l45',10,NULL,'choice','{"stem":"How soon after the birth did reporters arrive?","options":["The day after the birth, sixty of them came by airplane","They never came","Only one reporter came","A full year later"],"answer_index":0,"audio":"In democratic countries, any attempt to restrict the freedom of the press is rightly condemned. However, this freedom can easily be abused. Stories about people often attract far more public attention than political events. Though we may enjoy reading about the lives of others, it is extremely doubtful whether we would enjoy reading about ourselves. Acting on the contention that facts are sacred, reporters can cause untold suffering to individuals by publishing details about their private lives. Newspapers exert such tremendous influence that they can not only bring about major changes in the lives of ordinary people but can even help overthrow a government. The story of a poor family that acquired fame and fortune overnight dramatically illustrates the power of the press. The family lived in a small town of twenty-three thousand people in South Dakota. As the parents already had five children, life was a perpetual struggle against poverty. They were expecting their sixth child and faced even more pressing money problems. If they had only had one more child, the fact would have passed unnoticed. They would have gone on struggling against economic odds and would have lived in obscurity. But they suddenly became the parents of quintuplets — four girls and a boy — an event that radically changed their lives. The day after the birth of the five children, an airplane arrived in town carrying sixty reporters and photographers. The rise to fame was swift. Television cameras and newspapers carried the news to everyone in the country. Newspapers and magazines offered the family huge sums for the exclusive rights to publish stories and photographs. Gifts poured in, not only from strangers but from baby-food and soap companies that wanted to advertise their products. The old farmhouse the family lived in was to be replaced by a new five-hundred-thousand-dollar home. Reporters kept pressing for interviews, so lawyers had to be hired to act as spokesmen at press conferences. While the five babies were still sleeping quietly in oxygen tents in a hospital nursery, their parents were already paying the price of fame. It would never again be possible for them to lead normal lives. They had become the victims of commercialization, for their names had acquired a market value. Instead of being five new members of a family, these children had instantly become a commodity.","explanation_cn":"课文说五个孩子出生第二天,一架飞机带来六十名记者和摄影师。✓ the day after; sixty reporters by airplane."}'::jsonb,9) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l45',10,NULL,'choice','{"stem":"Where were the five babies while their parents dealt with the press?","options":["At home with relatives","In a new mansion","Sleeping in oxygen tents in a hospital nursery","On a television set"],"answer_index":2,"audio":"In democratic countries, any attempt to restrict the freedom of the press is rightly condemned. However, this freedom can easily be abused. Stories about people often attract far more public attention than political events. Though we may enjoy reading about the lives of others, it is extremely doubtful whether we would enjoy reading about ourselves. Acting on the contention that facts are sacred, reporters can cause untold suffering to individuals by publishing details about their private lives. Newspapers exert such tremendous influence that they can not only bring about major changes in the lives of ordinary people but can even help overthrow a government. The story of a poor family that acquired fame and fortune overnight dramatically illustrates the power of the press. The family lived in a small town of twenty-three thousand people in South Dakota. As the parents already had five children, life was a perpetual struggle against poverty. They were expecting their sixth child and faced even more pressing money problems. If they had only had one more child, the fact would have passed unnoticed. They would have gone on struggling against economic odds and would have lived in obscurity. But they suddenly became the parents of quintuplets — four girls and a boy — an event that radically changed their lives. The day after the birth of the five children, an airplane arrived in town carrying sixty reporters and photographers. The rise to fame was swift. Television cameras and newspapers carried the news to everyone in the country. Newspapers and magazines offered the family huge sums for the exclusive rights to publish stories and photographs. Gifts poured in, not only from strangers but from baby-food and soap companies that wanted to advertise their products. The old farmhouse the family lived in was to be replaced by a new five-hundred-thousand-dollar home. Reporters kept pressing for interviews, so lawyers had to be hired to act as spokesmen at press conferences. While the five babies were still sleeping quietly in oxygen tents in a hospital nursery, their parents were already paying the price of fame. It would never again be possible for them to lead normal lives. They had become the victims of commercialization, for their names had acquired a market value. Instead of being five new members of a family, these children had instantly become a commodity.","explanation_cn":"课文说五个婴儿还静静睡在医院育婴室的氧气帐里。✓ oxygen tents in a hospital nursery."}'::jsonb,10) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
